CREATE OR REPLACE FUNCTION public.accept_proposal_by_token(_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  p public.internal_proposals;
  new_deal_id uuid;
  mid_value numeric;
BEGIN
  SELECT * INTO p FROM public.internal_proposals WHERE accept_token = _token LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_TOKEN');
  END IF;

  IF p.status = 'accepted' THEN
    RETURN jsonb_build_object('ok', true, 'already_accepted', true, 'proposal_id', p.id, 'deal_id', p.deal_id);
  END IF;

  IF p.status IN ('rejected','expired') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PROPOSAL_'|| upper(p.status::text));
  END IF;

  -- Estimate mid-point for the deal value
  mid_value := 50000; -- safe fallback

  UPDATE public.internal_proposals
     SET status = 'accepted', accepted_at = now(), updated_at = now()
   WHERE id = p.id;

  -- Create the deal (handle_deal_won trigger will create the invoice + flip contact to CLIENT)
  IF p.deal_id IS NULL THEN
    INSERT INTO public.deals (
      contact_id, business_name, deal_name,
      estimated_value_min, estimated_value_max, currency,
      status, notes, won_at
    ) VALUES (
      p.contact_id,
      COALESCE(p.business_name,''),
      COALESCE(NULLIF(p.title,''), 'Accepted proposal') ,
      mid_value, mid_value, 'GBP',
      'WON', 'Auto-created from accepted proposal ' || p.id::text, now()
    ) RETURNING id INTO new_deal_id;

    UPDATE public.internal_proposals SET deal_id = new_deal_id WHERE id = p.id;
  ELSE
    UPDATE public.deals SET status = 'WON', won_at = COALESCE(won_at, now()), updated_at = now()
     WHERE id = p.deal_id;
    new_deal_id := p.deal_id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'proposal_id', p.id, 'deal_id', new_deal_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.acquire_ai_lease(_request_id text, _agent_id uuid, _business_id uuid, _agent_capacity integer, _business_capacity integer, _provider text, _model text, _ttl_seconds integer DEFAULT 180)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  now_ts timestamptz := now();
  exp_ts timestamptz := now() + make_interval(secs => GREATEST(_ttl_seconds, 30));
  agent_in_use int := 0;
  business_in_use int := 0;
  lease_key_v text;
BEGIN
  -- opportunistic sweep of expired leases in the scopes we care about
  UPDATE public.ai_concurrency_leases
     SET status='expired', released_at = now_ts
   WHERE status='active'
     AND expires_at < now_ts
     AND (
       (_agent_id IS NOT NULL AND agent_id = _agent_id)
       OR (_business_id IS NOT NULL AND business_id = _business_id)
     );

  -- Serialise within scope only (no global serial bottleneck)
  IF _agent_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('ai_lease_agent:' || _agent_id::text, 0));
    SELECT count(*) INTO agent_in_use
      FROM public.ai_concurrency_leases
     WHERE agent_id = _agent_id AND status='active' AND expires_at > now_ts;
    IF _agent_capacity > 0 AND agent_in_use >= _agent_capacity THEN
      RETURN jsonb_build_object(
        'ok', false, 'reason', 'agent_concurrency_limit',
        'in_use', agent_in_use, 'capacity', _agent_capacity
      );
    END IF;
  END IF;

  IF _business_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('ai_lease_business:' || _business_id::text, 0));
    SELECT count(*) INTO business_in_use
      FROM public.ai_concurrency_leases
     WHERE business_id = _business_id AND status='active' AND expires_at > now_ts;
    IF _business_capacity > 0 AND business_in_use >= _business_capacity THEN
      RETURN jsonb_build_object(
        'ok', false, 'reason', 'business_concurrency_limit',
        'in_use', business_in_use, 'capacity', _business_capacity
      );
    END IF;
  END IF;

  lease_key_v := COALESCE(
    'agent:' || _agent_id::text,
    'business:' || _business_id::text,
    'global'
  );

  INSERT INTO public.ai_concurrency_leases
    (lease_key, request_id, agent_id, business_id, provider, model, expires_at)
  VALUES
    (lease_key_v, _request_id, _agent_id, _business_id, _provider, _model, exp_ts);

  RETURN jsonb_build_object(
    'ok', true,
    'expires_at', exp_ts,
    'agent_in_use', agent_in_use + CASE WHEN _agent_id IS NOT NULL THEN 1 ELSE 0 END,
    'business_in_use', business_in_use + CASE WHEN _business_id IS NOT NULL THEN 1 ELSE 0 END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.activate_outreach_campaign(_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c public.outreach_campaigns%ROWTYPE;
  v_mode text;
  v_seq_count int;
  v_contact_count int;
  v_inbox public.inboxes%ROWTYPE;
  v_has_creds boolean;
  v_business_live boolean;
  v_effective_mode text;
BEGIN
  SELECT * INTO c FROM public.outreach_campaigns WHERE id = _campaign_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'campaign not found'; END IF;

  v_mode := public.get_system_mode();
  v_business_live := public.has_live_ready_inbox(c.business_name);

  SELECT COUNT(*) INTO v_seq_count FROM public.outreach_sequences WHERE campaign_id = _campaign_id;
  IF v_seq_count = 0 THEN
    RAISE EXCEPTION 'cannot activate: no sequence steps defined' USING ERRCODE='check_violation';
  END IF;

  SELECT COUNT(*) INTO v_contact_count FROM public.contacts WHERE assigned_business = c.business_name;
  IF v_contact_count = 0 THEN
    RAISE EXCEPTION 'cannot activate: no contacts found for business %', c.business_name USING ERRCODE='check_violation';
  END IF;

  IF v_mode = 'live' OR v_business_live THEN
    SELECT * INTO v_inbox FROM public.inboxes
     WHERE business_name = c.business_name
       AND active = true
       AND provider_type = 'ionos_smtp'::public.inbox_provider_type
       AND live_readiness = 'live_ready'::public.inbox_live_readiness
     ORDER BY last_test_send_at DESC NULLS LAST, created_at DESC LIMIT 1;
    IF NOT FOUND THEN
      IF v_mode = 'live' THEN
        RAISE EXCEPTION 'cannot activate in live mode: no Live Ready inbox for business %', c.business_name USING ERRCODE='check_violation';
      END IF;
    ELSE
      IF v_inbox.last_test_send_status IS DISTINCT FROM 'passed' THEN
        RAISE EXCEPTION 'cannot activate: inbox % has not passed a real test send', v_inbox.email_address USING ERRCODE='check_violation';
      END IF;
      SELECT EXISTS(SELECT 1 FROM public.inbox_credentials WHERE inbox_id = v_inbox.id AND smtp_password_enc IS NOT NULL)
        INTO v_has_creds;
      IF NOT v_has_creds THEN
        RAISE EXCEPTION 'cannot activate: inbox % has no provider credentials', v_inbox.email_address USING ERRCODE='check_violation';
      END IF;
    END IF;
  END IF;

  v_effective_mode := CASE
    WHEN v_mode = 'live' THEN 'live'
    WHEN v_business_live THEN 'business_live'
    ELSE 'simulated'
  END;

  UPDATE public.outreach_campaigns SET status = 'active' WHERE id = _campaign_id;

  INSERT INTO public.activity_log (event_type, description, entity_type, entity_id)
  VALUES ('campaign_activated',
    format('Campaign %s activated in %s mode (business=%s)', c.campaign_name, v_effective_mode, c.business_name),
    'outreach_campaign', _campaign_id);

  RETURN jsonb_build_object('ok', true, 'mode', v_effective_mode, 'system_mode', v_mode, 'business_live', v_business_live);
END;
$function$

CREATE OR REPLACE FUNCTION public.apollo_credit_release(_operation_key text, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  res public.apollo_credit_reservations%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('apollo_credit_firewall'));
  SELECT * INTO res FROM public.apollo_credit_reservations WHERE operation_key = _operation_key FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'reservation_not_found');
  END IF;
  IF res.status <> 'reserved' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_' || res.status, 'idempotent', true);
  END IF;
  UPDATE public.apollo_credit_reservations
     SET status = 'released', release_reason = _reason, updated_at = now()
   WHERE id = res.id;
  RETURN jsonb_build_object('ok', true, 'reservation_id', res.id, 'released', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.apollo_credit_reserve(_operation_key text, _function_source text, _estimated_credits integer, _business_name text DEFAULT NULL::text, _business_id uuid DEFAULT NULL::uuid, _run_id text DEFAULT NULL::text, _apollo_person_ids text[] DEFAULT ARRAY[]::text[], _metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  pol public.apollo_portfolio_credit_policy%ROWTYPE;
  existing public.apollo_credit_reservations%ROWTYPE;
  used integer;
  reserved integer;
  available integer;
  new_id uuid;
BEGIN
  IF _operation_key IS NULL OR length(trim(_operation_key)) = 0 THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'operation_key_required');
  END IF;
  IF _estimated_credits IS NULL OR _estimated_credits < 0 THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'invalid_estimate');
  END IF;

  -- Serialise every portfolio reservation decision.
  PERFORM pg_advisory_xact_lock(hashtext('apollo_credit_firewall'));

  SELECT * INTO existing FROM public.apollo_credit_reservations WHERE operation_key = _operation_key;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'duplicate_operation_key',
      'existing_status', existing.status,
      'reservation_id', existing.id,
      'idempotent', true
    );
  END IF;

  SELECT * INTO pol FROM public.apollo_portfolio_credit_policy WHERE provider = 'apollo';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'policy_missing');
  END IF;
  IF NOT pol.paid_enrichment_enabled THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'paid_enrichment_disabled');
  END IF;
  IF pol.hard_credit_limit <= 0 THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'hard_credit_limit_zero');
  END IF;
  IF _estimated_credits > pol.per_run_cap THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'per_run_cap_exceeded',
      'per_run_cap', pol.per_run_cap, 'requested', _estimated_credits);
  END IF;

  SELECT COALESCE(SUM(credits_used), 0) INTO used FROM public.apollo_credit_ledger;
  SELECT COALESCE(SUM(estimated_credits), 0) INTO reserved
    FROM public.apollo_credit_reservations WHERE status = 'reserved';
  available := pol.hard_credit_limit - pol.safety_reserve - used - reserved;

  IF _estimated_credits > available THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'hard_limit_would_be_exceeded',
      'credits_available', GREATEST(0, available), 'requested', _estimated_credits);
  END IF;

  INSERT INTO public.apollo_credit_reservations (
    operation_key, business_name, business_id, function_source, run_id,
    apollo_person_ids, estimated_credits, status, metadata
  ) VALUES (
    _operation_key, _business_name, _business_id, _function_source, _run_id,
    COALESCE(_apollo_person_ids, ARRAY[]::text[]), _estimated_credits, 'reserved', COALESCE(_metadata, '{}'::jsonb)
  ) RETURNING id INTO new_id;

  RETURN jsonb_build_object(
    'allowed', true,
    'reservation_id', new_id,
    'operation_key', _operation_key,
    'estimated_credits', _estimated_credits,
    'credits_available_after', GREATEST(0, available - _estimated_credits)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apollo_credit_settle(_operation_key text, _actual_credits integer, _no_email_person_ids text[] DEFAULT ARRAY[]::text[], _revealed_person_ids text[] DEFAULT ARRAY[]::text[], _metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  res public.apollo_credit_reservations%ROWTYPE;
  led_id uuid;
  pid text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('apollo_credit_firewall'));

  SELECT * INTO res FROM public.apollo_credit_reservations WHERE operation_key = _operation_key FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'reservation_not_found');
  END IF;
  IF res.status <> 'reserved' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_' || res.status,
      'idempotent', true, 'ledger_id', res.ledger_id, 'actual_credits', res.actual_credits);
  END IF;

  INSERT INTO public.apollo_credit_ledger (
    business_name, business_id, function_source, credits_used, apollo_person_ids, metadata
  ) VALUES (
    COALESCE(res.business_name, 'portfolio'), res.business_id, res.function_source,
    GREATEST(0, COALESCE(_actual_credits, 0)), res.apollo_person_ids,
    COALESCE(_metadata, '{}'::jsonb) || jsonb_build_object('operation_key', _operation_key, 'reservation_id', res.id)
  ) RETURNING id INTO led_id;

  UPDATE public.apollo_credit_reservations
     SET status = 'settled',
         actual_credits = GREATEST(0, COALESCE(_actual_credits, 0)),
         ledger_id = led_id,
         settled_at = now(),
         updated_at = now()
   WHERE id = res.id;

  FOREACH pid IN ARRAY COALESCE(_no_email_person_ids, ARRAY[]::text[]) LOOP
    INSERT INTO public.apollo_paid_attempts (apollo_person_id, outcome, function_source, operation_key)
    VALUES (pid, 'no_email', res.function_source, _operation_key)
    ON CONFLICT (provider, apollo_person_id)
    DO UPDATE SET attempts = public.apollo_paid_attempts.attempts + 1,
                  outcome = 'no_email',
                  last_attempt_at = now(),
                  operation_key = EXCLUDED.operation_key;
  END LOOP;

  FOREACH pid IN ARRAY COALESCE(_revealed_person_ids, ARRAY[]::text[]) LOOP
    INSERT INTO public.apollo_paid_attempts (apollo_person_id, outcome, function_source, operation_key)
    VALUES (pid, 'email_returned', res.function_source, _operation_key)
    ON CONFLICT (provider, apollo_person_id)
    DO UPDATE SET attempts = public.apollo_paid_attempts.attempts + 1,
                  outcome = 'email_returned',
                  last_attempt_at = now(),
                  operation_key = EXCLUDED.operation_key;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'ledger_id', led_id, 'reservation_id', res.id,
    'actual_credits', GREATEST(0, COALESCE(_actual_credits, 0)));
END;
$function$

CREATE OR REPLACE FUNCTION public.apollo_credit_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  pol public.apollo_portfolio_credit_policy%ROWTYPE;
  used integer;
  reserved integer;
BEGIN
  IF auth.uid() IS NOT NULL
     AND NOT (public.has_role(auth.uid(), 'founder') OR public.has_role(auth.uid(), 'admin')) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  SELECT * INTO pol FROM public.apollo_portfolio_credit_policy WHERE provider = 'apollo';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'policy_missing', 'paid_enrichment_enabled', false);
  END IF;
  SELECT COALESCE(SUM(credits_used), 0) INTO used FROM public.apollo_credit_ledger;
  SELECT COALESCE(SUM(estimated_credits), 0) INTO reserved
    FROM public.apollo_credit_reservations WHERE status = 'reserved';
  RETURN jsonb_build_object(
    'ok', true,
    'provider', pol.provider,
    'paid_enrichment_enabled', pol.paid_enrichment_enabled,
    'hard_credit_limit', pol.hard_credit_limit,
    'safety_reserve', pol.safety_reserve,
    'per_run_cap', pol.per_run_cap,
    'allow_phone_reveal', pol.allow_phone_reveal,
    'allow_personal_email_reveal', pol.allow_personal_email_reveal,
    'allow_waterfall', pol.allow_waterfall,
    'credits_used', used,
    'credits_reserved', reserved,
    'credits_remaining', GREATEST(0, pol.hard_credit_limit - pol.safety_reserve - used - reserved)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apollo_decrypt_key(cipher bytea, enc_key text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF cipher IS NULL THEN RETURN NULL; END IF;
  IF enc_key IS NULL OR length(enc_key) = 0 THEN RAISE EXCEPTION 'missing_encryption_key'; END IF;
  RETURN extensions.pgp_sym_decrypt(cipher, enc_key);
END;
$function$

CREATE OR REPLACE FUNCTION public.apollo_encrypt_key(plain text, enc_key text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF plain IS NULL OR length(plain) = 0 THEN RETURN NULL; END IF;
  IF enc_key IS NULL OR length(enc_key) = 0 THEN RAISE EXCEPTION 'missing_encryption_key'; END IF;
  RETURN extensions.pgp_sym_encrypt(plain, enc_key);
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_reply_stop_suppression(p_contact_id uuid, p_message_body text, p_source text DEFAULT 'inbound_message'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_body text; v_match boolean := false;
BEGIN
  IF p_contact_id IS NULL OR p_message_body IS NULL THEN RETURN false; END IF;
  v_body := lower(p_message_body);
  IF v_body ~ '(^|\W)(unsubscribe|stop|remove me|do not contact|don''?t contact me|no further emails)(\W|$)' THEN
    v_match := true;
  END IF;
  IF NOT v_match THEN RETURN false; END IF;
  UPDATE public.contacts
     SET is_globally_suppressed=true, status='DO_NOT_CONTACT'::contact_status,
         compliance_status='do_not_contact',
         do_not_contact_at=COALESCE(do_not_contact_at, now()),
         do_not_contact_reason=COALESCE(NULLIF(do_not_contact_reason,''),'reply_stop_request'),
         global_suppression_reason=COALESCE(global_suppression_reason,'reply_stop_request'),
         global_suppression_at=COALESCE(global_suppression_at, now())
   WHERE id=p_contact_id;
  INSERT INTO public.contact_compliance_events (contact_id, event_type, event_source, event_notes, new_value, actor)
  VALUES (p_contact_id,'reply_stop_suppressed', p_source,
          'Inbound message contained opt-out wording',
          jsonb_build_object('snippet', left(p_message_body, 240)),'system');
  RETURN true;
END; $function$

CREATE OR REPLACE FUNCTION public.apply_reputation_event(_inbox_id uuid, _contact_id uuid, _event reputation_event_type, _details text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  impact int := 0;
  dom_id uuid;
  new_score int;
  ib public.inboxes;
BEGIN
  IF _inbox_id IS NULL THEN RETURN; END IF;
  impact := CASE _event
    WHEN 'bounce'    THEN -10
    WHEN 'spam'      THEN -25
    WHEN 'open'      THEN  +2
    WHEN 'reply'     THEN  +5
    ELSE 0
  END;

  dom_id := public.domain_for_inbox(_inbox_id);

  INSERT INTO public.reputation_events (inbox_id, domain_id, contact_id, event_type, impact_score, details)
  VALUES (_inbox_id, dom_id, _contact_id, _event, impact, coalesce(_details,''));

  IF impact <> 0 THEN
    SELECT * INTO ib FROM public.inboxes WHERE id = _inbox_id;
    new_score := GREATEST(0, LEAST(100, ib.reputation_score + impact));
    UPDATE public.inboxes
       SET reputation_score = new_score, updated_at = now()
     WHERE id = _inbox_id;

    IF new_score < 40 AND ib.reputation_score >= 40 THEN
      INSERT INTO public.activity_log (event_type, description, entity_type, entity_id)
      VALUES ('reputation_drop',
              'Inbox '||ib.email_address||' reputation dropped to '||new_score||' — sending volume halved',
              'inbox', _inbox_id);
    END IF;
    IF new_score < 20 AND ib.reputation_score >= 20 THEN
      INSERT INTO public.activity_log (event_type, description, entity_type, entity_id)
      VALUES ('reputation_drop',
              'Inbox '||ib.email_address||' reputation dropped to '||new_score||' — sending paused',
              'inbox', _inbox_id);
    END IF;

    IF dom_id IS NOT NULL THEN
      UPDATE public.sending_domains
         SET reputation_score = GREATEST(0, LEAST(100, reputation_score + impact)),
             updated_at = now()
       WHERE id = dom_id;
    END IF;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.assign_inbox_for_contact(_contact_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c public.contacts%ROWTYPE;
  picked_inbox_id uuid;
BEGIN
  SELECT * INTO c FROM public.contacts WHERE id = _contact_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  IF c.assigned_inbox_id IS NOT NULL THEN
    RETURN c.assigned_inbox_id;
  END IF;

  SELECT id INTO picked_inbox_id
    FROM public.inboxes
   WHERE active = true
     AND (c.assigned_business = '' OR business_name = c.assigned_business)
     AND current_send_count < daily_send_limit
   ORDER BY current_send_count ASC, created_at ASC
   LIMIT 1;

  IF picked_inbox_id IS NULL THEN RETURN NULL; END IF;

  UPDATE public.contacts SET assigned_inbox_id = picked_inbox_id, updated_at = now()
   WHERE id = _contact_id;

  RETURN picked_inbox_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_resolve_system_events()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  resolved_count int := 0;
  r record;
BEGIN
  FOR r IN
    SELECT se.id, se.entity_id FROM public.system_events se
     WHERE se.event_type = 'email_queue_stuck' AND se.resolved = false
  LOOP
    IF EXISTS (SELECT 1 FROM public.email_queue
                WHERE id = r.entity_id
                  AND (status IN ('sent','blocked','failed') OR scheduled_at > now())) THEN
      UPDATE public.system_events SET resolved = true, resolved_at = now(),
             resolution_note = 'Queue item progressed' WHERE id = r.id;
      resolved_count := resolved_count + 1;
    END IF;
  END LOOP;

  FOR r IN
    SELECT se.id, se.entity_id FROM public.system_events se
     WHERE se.event_type = 'assignment_idle' AND se.resolved = false
  LOOP
    IF EXISTS (SELECT 1 FROM public.assignments
                WHERE id = r.entity_id
                  AND (updated_at > now() - interval '6 hours'
                       OR status::text IN ('completed','failed'))) THEN
      UPDATE public.system_events SET resolved = true, resolved_at = now(),
             resolution_note = 'Assignment progressed' WHERE id = r.id;
      resolved_count := resolved_count + 1;
    END IF;
  END LOOP;

  FOR r IN
    SELECT se.id, se.entity_id FROM public.system_events se
     WHERE se.event_type = 'invoice_overdue_14d' AND se.resolved = false
  LOOP
    IF EXISTS (SELECT 1 FROM public.invoices
                WHERE id = r.entity_id AND status = 'PAID') THEN
      UPDATE public.system_events SET resolved = true, resolved_at = now(),
             resolution_note = 'Invoice paid' WHERE id = r.id;
      resolved_count := resolved_count + 1;
    END IF;
  END LOOP;

  FOR r IN
    SELECT se.id, se.entity_id, se.entity_type FROM public.system_events se
     WHERE se.event_type = 'compliance_score_high' AND se.resolved = false
  LOOP
    IF EXISTS (SELECT 1 FROM public.compliance_scores
                WHERE entity_id = r.entity_id
                  AND entity_type::text = r.entity_type
                  AND score <= 70) THEN
      UPDATE public.system_events SET resolved = true, resolved_at = now(),
             resolution_note = 'Compliance score recovered' WHERE id = r.id;
      resolved_count := resolved_count + 1;
    END IF;
  END LOOP;

  FOR r IN
    SELECT se.id, se.entity_id FROM public.system_events se
     WHERE se.event_type = 'inbox_reputation_critical' AND se.resolved = false
  LOOP
    IF EXISTS (SELECT 1 FROM public.inboxes
                WHERE id = r.entity_id AND reputation_score >= 40) THEN
      UPDATE public.system_events SET resolved = true, resolved_at = now(),
             resolution_note = 'Inbox reputation recovered' WHERE id = r.id;
      resolved_count := resolved_count + 1;
    END IF;
  END LOOP;

  RETURN resolved_count;
END; $function$

CREATE OR REPLACE FUNCTION public.cancel_queue_on_inbound_comm()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.direction = 'inbound' THEN
    UPDATE public.email_queue
      SET status = 'blocked', block_reason = 'REPLY_RECEIVED'
      WHERE contact_id = NEW.contact_id AND status = 'pending';
    UPDATE public.contacts SET active_campaign_id = NULL WHERE id = NEW.contact_id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_outreach_allowed(_contact_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c public.contacts%ROWTYPE;
  recent_bounce boolean;
  recent_real_outbound timestamptz;
  recent_inbound timestamptz;
  recent_last_contacted_real boolean;
BEGIN
  SELECT * INTO c FROM public.contacts WHERE id = _contact_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'CONTACT_NOT_FOUND');
  END IF;

  IF c.status = 'DO_NOT_CONTACT' THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'DO_NOT_CONTACT');
  END IF;

  IF c.status IN ('ENGAGED', 'QUALIFIED', 'CLIENT') THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'STATUS_BLOCKED', 'status', c.status);
  END IF;

  IF c.conversation_active = true THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'CONVERSATION_ACTIVE');
  END IF;

  -- Block on any genuine inbound communication in last 24h (always real, never synthetic)
  SELECT MAX(timestamp) INTO recent_inbound
    FROM public.communications
   WHERE contact_id = _contact_id
     AND direction = 'inbound'
     AND ignored_for_send_check = false
     AND timestamp > (now() - interval '24 hours');

  IF recent_inbound IS NOT NULL THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'RECENT_COMMUNICATION_24H',
      'detail', 'recent_inbound_reply',
      'last_communication_at', recent_inbound
    );
  END IF;

  -- Block on outbound communication in last 24h ONLY when it represents a real SMTP send.
  -- A real outbound is one that has a corresponding email_queue row with smtp_accepted_at populated
  -- within the last 24 hours, OR a non-ignored manual/founder communication.
  SELECT MAX(cm.timestamp) INTO recent_real_outbound
    FROM public.communications cm
   WHERE cm.contact_id = _contact_id
     AND cm.direction = 'outbound'
     AND cm.ignored_for_send_check = false
     AND cm.timestamp > (now() - interval '24 hours')
     AND (
       -- Real SMTP-backed: there is an email_queue row marking actual SMTP acceptance
       EXISTS (
         SELECT 1 FROM public.email_queue eq
          WHERE eq.contact_id = _contact_id
            AND eq.smtp_accepted_at IS NOT NULL
            AND eq.smtp_accepted_at > (now() - interval '24 hours')
       )
       -- Or a manual/non-AI communication (founder/human) — treat as real
       OR cm.ai_generated = false
     );

  IF recent_real_outbound IS NOT NULL THEN
    -- Double check: if the only matching cm is a non-AI but no real SMTP, still block (manual contact)
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'RECENT_COMMUNICATION_24H',
      'detail', 'recent_real_smtp',
      'last_communication_at', recent_real_outbound
    );
  END IF;

  -- last_contacted_at < 48h: only honor when there is a real SMTP-backed send corroborating it
  IF c.last_contacted_at IS NOT NULL AND c.last_contacted_at > (now() - interval '48 hours') THEN
    SELECT EXISTS(
      SELECT 1 FROM public.email_queue eq
       WHERE eq.contact_id = _contact_id
         AND eq.smtp_accepted_at IS NOT NULL
         AND eq.smtp_accepted_at > (now() - interval '48 hours')
    ) INTO recent_last_contacted_real;

    IF recent_last_contacted_real THEN
      RETURN jsonb_build_object(
        'allowed', false,
        'reason', 'RECENTLY_CONTACTED',
        'detail', 'recent_real_smtp',
        'last_contacted_at', c.last_contacted_at
      );
    END IF;
    -- else: stale/ghost stamp from simulated/failed send — do not block
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM public.email_events
     WHERE contact_id = _contact_id AND event_type = 'bounced'
  ) INTO recent_bounce;

  IF recent_bounce THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'EMAIL_BOUNCED');
  END IF;

  IF c.assigned_inbox_id IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'NO_INBOX_ASSIGNED');
  END IF;

  RETURN jsonb_build_object('allowed', true, 'inbox_id', c.assigned_inbox_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.check_outreach_allowed(p_contact_id uuid, p_business_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c public.contacts%ROWTYPE;
  bcr public.business_contact_relationships%ROWTYPE;
  reasons text[] := ARRAY[]::text[];
  retention_valid boolean := false;
  unsub_present boolean := false;
  basis_present boolean := false;
BEGIN
  SELECT * INTO c FROM public.contacts WHERE id=p_contact_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('allowed', false, 'blocker_reasons', ARRAY['contact_not_found']); END IF;
  basis_present := c.lawful_basis IS NOT NULL AND length(c.lawful_basis) > 0;
  unsub_present := c.unsubscribe_token IS NOT NULL;
  retention_valid := c.retention_until IS NOT NULL AND c.retention_until > now();
  IF NOT basis_present THEN reasons := reasons || 'no_lawful_basis'; END IF;
  IF NOT unsub_present THEN reasons := reasons || 'no_unsubscribe_token'; END IF;
  IF NOT retention_valid THEN reasons := reasons || 'retention_invalid_or_expired'; END IF;
  IF c.is_globally_suppressed THEN reasons := reasons || 'globally_suppressed'; END IF;
  IF c.hard_bounced THEN reasons := reasons || 'hard_bounced'; END IF;
  IF c.unsubscribed_at IS NOT NULL THEN reasons := reasons || 'unsubscribed'; END IF;
  IF c.status='DO_NOT_CONTACT'::contact_status THEN reasons := reasons || 'status_do_not_contact'; END IF;
  IF c.compliance_status IN ('unsubscribed','hard_bounced','do_not_contact','pending_review','retained_no_outreach') THEN
    reasons := reasons || ('compliance_status_' || c.compliance_status);
  END IF;
  IF p_business_id IS NOT NULL THEN
    SELECT * INTO bcr FROM public.business_contact_relationships WHERE contact_id=p_contact_id AND business_id=p_business_id LIMIT 1;
    IF FOUND THEN
      IF bcr.do_not_contact THEN reasons := reasons || 'bcr_do_not_contact'; END IF;
      IF NOT bcr.campaign_eligible THEN reasons := reasons || 'bcr_not_campaign_eligible'; END IF;
      IF bcr.qualification <> 'qualified'::bcr_qualification THEN reasons := reasons || 'bcr_not_qualified'; END IF;
    ELSE
      reasons := reasons || 'bcr_missing';
    END IF;
  END IF;
  RETURN jsonb_build_object(
    'allowed', array_length(reasons, 1) IS NULL,
    'blocker_reasons', reasons,
    'compliance_status', c.compliance_status,
    'unsubscribe_token_present', unsub_present,
    'lawful_basis_present', basis_present,
    'retention_valid', retention_valid
  );
END; $function$

CREATE OR REPLACE FUNCTION public.check_send_throttle(_inbox_id uuid, _contact_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ib record;
  ct record;
  domain_name text;
  domain_score integer;
  domain_usage integer;
  domain_limit integer;
  warmup_max integer;
  days_in integer;
  effective_daily_limit integer;
  start_hr integer := 8;
  end_hr integer := 17;
  current_hr_local integer;
  is_reply_priority boolean := false;
BEGIN
  SELECT * INTO ib FROM public.inboxes WHERE id = _inbox_id;
  IF ib IS NULL THEN RETURN jsonb_build_object('allowed', false, 'reason', 'INBOX_NOT_FOUND'); END IF;

  SELECT * INTO ct FROM public.contacts WHERE id = _contact_id;
  IF ct IS NULL THEN RETURN jsonb_build_object('allowed', false, 'reason', 'CONTACT_NOT_FOUND'); END IF;

  -- Reply-first priority: if contact has replied, bypass window/throttle (still respect hard reputation pause)
  is_reply_priority := ct.last_replied_at IS NOT NULL
                       AND ct.last_replied_at > now() - interval '14 days';

  -- ===== HARD STOPS (apply even to reply priority) =====
  IF NOT ib.active THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'INBOX_INACTIVE',
      'retry_at', (now() + interval '6 hours')::text);
  END IF;

  IF ib.reputation_score < 20 THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'REPUTATION_PAUSE',
      'retry_at', (now() + interval '24 hours')::text);
  END IF;

  -- Domain reputation shield
  domain_name := split_part(ib.email_address, '@', 2);
  SELECT domain_reputation_score, current_usage, daily_limit
  INTO domain_score, domain_usage, domain_limit
  FROM public.sending_domains
  WHERE sending_domains.domain_name = check_send_throttle.domain_name;

  IF domain_score IS NOT NULL AND domain_score < 20 THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'DOMAIN_REPUTATION_PAUSE',
      'retry_at', (now() + interval '24 hours')::text);
  END IF;

  -- ===== Reply-priority skips remaining checks =====
  IF is_reply_priority THEN
    RETURN jsonb_build_object('allowed', true, 'reason', 'REPLY_PRIORITY_BYPASS');
  END IF;

  -- ===== WARMUP CAP =====
  days_in := GREATEST(0, EXTRACT(EPOCH FROM (now() - ib.warmup_started_at))::int / 86400);
  warmup_max := CASE
    WHEN days_in < 3 THEN 10
    WHEN days_in < 7 THEN 25
    WHEN days_in < 14 THEN 50
    ELSE ib.daily_send_limit
  END;
  effective_daily_limit := LEAST(warmup_max, ib.daily_send_limit);

  -- Reduce by half if reputation borderline
  IF ib.reputation_score < 40 THEN
    effective_daily_limit := effective_daily_limit / 2;
  END IF;

  -- Reduce by half if domain reputation borderline
  IF domain_score IS NOT NULL AND domain_score < 40 THEN
    effective_daily_limit := effective_daily_limit / 2;
  END IF;

  -- ===== DAILY LIMIT =====
  IF ib.current_send_count >= effective_daily_limit THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'DAILY_LIMIT_REACHED',
      'retry_at', (date_trunc('day', now()) + interval '1 day' + interval '8 hours')::text);
  END IF;

  -- ===== HOURLY LIMIT =====
  IF ib.hourly_window_start < now() - interval '1 hour' THEN
    UPDATE public.inboxes SET hourly_send_count = 0, hourly_window_start = now() WHERE id = _inbox_id;
  ELSIF ib.hourly_send_count >= ib.hourly_send_limit THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'HOURLY_LIMIT_REACHED',
      'retry_at', (ib.hourly_window_start + interval '1 hour')::text);
  END IF;

  -- ===== DOMAIN DAILY LIMIT =====
  IF domain_limit IS NOT NULL AND domain_usage >= domain_limit THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'DOMAIN_DAILY_LIMIT',
      'retry_at', (date_trunc('day', now()) + interval '1 day' + interval '8 hours')::text);
  END IF;

  -- ===== SEND WINDOW (timezone-aware, widened for low confidence) =====
  IF ct.timezone_confidence = 'low' THEN
    start_hr := 7;
    end_hr := 19;
  ELSIF ct.timezone_confidence = 'medium' THEN
    start_hr := 8;
    end_hr := 18;
  ELSE
    start_hr := 8;
    end_hr := 17;
  END IF;

  -- Use contact timezone if present, fall back to UTC
  BEGIN
    current_hr_local := EXTRACT(HOUR FROM (now() AT TIME ZONE COALESCE(NULLIF(ct.timezone, ''), 'UTC')))::int;
  EXCEPTION WHEN OTHERS THEN
    current_hr_local := EXTRACT(HOUR FROM (now() AT TIME ZONE 'UTC'))::int;
  END;

  IF current_hr_local < start_hr OR current_hr_local >= end_hr THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'OUTSIDE_SEND_WINDOW',
      'retry_at', (date_trunc('day', now()) + interval '1 day' + (start_hr || ' hours')::interval)::text);
  END IF;

  RETURN jsonb_build_object('allowed', true, 'reason', 'OK');
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_portfolio_contact(p_contact_id uuid, p_business_name text, p_campaign_key text DEFAULT NULL::text, p_campaign_id uuid DEFAULT NULL::uuid, p_founder_override boolean DEFAULT false, p_override_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contact public.contacts%ROWTYPE;
  v_owner public.portfolio_contact_ownership%ROWTYPE;
  v_business_id uuid;
  v_cooldown_days integer;
  v_cooldown_until timestamptz;
  v_hard text[] := '{}';
  v_soft text[] := '{}';
  v_new_id uuid;
BEGIN
  SELECT * INTO v_contact FROM public.contacts WHERE id = p_contact_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('decision', 'blocked', 'reason_codes', ARRAY['contact_not_found'], 'hard_blocked', true);
  END IF;

  SELECT cross_brand_cooldown_days INTO v_cooldown_days FROM public.portfolio_collision_policy LIMIT 1;
  v_cooldown_days := COALESCE(v_cooldown_days, 30);

  SELECT id INTO v_business_id FROM public.businesses WHERE name = p_business_name LIMIT 1;

  IF COALESCE(v_contact.is_globally_suppressed, false) THEN v_hard := v_hard || 'global_suppression'; END IF;
  IF COALESCE(v_contact.hard_bounced, false) THEN v_hard := v_hard || 'hard_bounce'; END IF;
  IF v_contact.unsubscribed_at IS NOT NULL THEN v_hard := v_hard || 'unsubscribed'; END IF;
  IF v_contact.do_not_contact_at IS NOT NULL THEN v_hard := v_hard || 'do_not_contact'; END IF;

  SELECT * INTO v_owner
  FROM public.portfolio_contact_ownership
  WHERE contact_id = p_contact_id AND status = 'active'
  FOR UPDATE;

  IF FOUND AND v_owner.business_name = p_business_name AND array_length(v_hard, 1) IS NULL THEN
    INSERT INTO public.portfolio_ownership_events
      (contact_id, ownership_id, business_name, campaign_key, event_type, decision, reason_codes, actor_id)
    VALUES (p_contact_id, v_owner.id, p_business_name, p_campaign_key, 'claim', 'allowed',
            ARRAY['already_owned_by_requesting_brand'], auth.uid());
    RETURN jsonb_build_object(
      'decision', 'allowed', 'reason_codes', ARRAY['already_owned_by_requesting_brand'],
      'hard_blocked', false, 'ownership_id', v_owner.id, 'current_owner_business', v_owner.business_name);
  END IF;

  IF COALESCE(v_contact.conversation_active, false)
     AND (NOT FOUND OR v_owner.business_name <> p_business_name) THEN
    v_hard := v_hard || 'active_conversation_block';
  END IF;

  IF FOUND AND v_owner.business_name <> p_business_name THEN
    v_soft := v_soft || 'owned_by_other_brand';
  END IF;

  SELECT max(cooldown_until) INTO v_cooldown_until
  FROM public.portfolio_contact_ownership
  WHERE contact_id = p_contact_id
    AND status = 'released'
    AND business_name <> p_business_name
    AND cooldown_until IS NOT NULL
    AND cooldown_until > now();
  IF v_cooldown_until IS NOT NULL THEN v_soft := v_soft || 'cross_brand_cooldown'; END IF;

  IF array_length(v_hard, 1) IS NOT NULL THEN
    INSERT INTO public.portfolio_ownership_events
      (contact_id, business_name, campaign_key, event_type, decision, reason_codes, founder_override, override_reason, actor_id)
    VALUES (p_contact_id, p_business_name, p_campaign_key, 'claim', 'blocked', v_hard || v_soft,
            COALESCE(p_founder_override, false), COALESCE(p_override_reason, ''), auth.uid());
    RETURN jsonb_build_object('decision', 'blocked', 'reason_codes', v_hard || v_soft,
      'hard_blocked', true, 'overridable', false,
      'explanation', 'Hard safety block; founder override cannot bypass this.');
  END IF;

  IF array_length(v_soft, 1) IS NOT NULL AND NOT COALESCE(p_founder_override, false) THEN
    INSERT INTO public.portfolio_ownership_events
      (contact_id, business_name, campaign_key, event_type, decision, reason_codes, actor_id)
    VALUES (p_contact_id, p_business_name, p_campaign_key, 'claim', 'blocked', v_soft, auth.uid());
    RETURN jsonb_build_object('decision', 'blocked', 'reason_codes', v_soft,
      'hard_blocked', false, 'overridable', true,
      'current_owner_business', v_owner.business_name,
      'cooldown_until', v_cooldown_until);
  END IF;

  IF v_owner.id IS NOT NULL AND v_owner.business_name <> p_business_name THEN
    UPDATE public.portfolio_contact_ownership
       SET status = 'released',
           released_at = now(),
           reason_code = 'released_by_founder_override',
           cooldown_until = now() + (v_cooldown_days || ' days')::interval,
           updated_at = now()
     WHERE id = v_owner.id;
    INSERT INTO public.portfolio_ownership_events
      (contact_id, ownership_id, business_name, event_type, decision, reason_codes, founder_override, override_reason, actor_id)
    VALUES (p_contact_id, v_owner.id, v_owner.business_name, 'release', 'allowed',
            ARRAY['released_by_founder_override'], true, COALESCE(p_override_reason, ''), auth.uid());
  END IF;

  INSERT INTO public.portfolio_contact_ownership
    (contact_id, business_id, business_name, campaign_key, campaign_id, status, reason_code,
     founder_override, override_reason, claimed_by)
  VALUES (p_contact_id, v_business_id, p_business_name, p_campaign_key, p_campaign_id, 'active',
          CASE WHEN COALESCE(p_founder_override, false) THEN 'claimed_with_override' ELSE 'claimed' END,
          COALESCE(p_founder_override, false), COALESCE(p_override_reason, ''), auth.uid())
  RETURNING id INTO v_new_id;

  INSERT INTO public.portfolio_ownership_events
    (contact_id, ownership_id, business_name, campaign_key, event_type, decision, reason_codes,
     founder_override, override_reason, actor_id)
  VALUES (p_contact_id, v_new_id, p_business_name, p_campaign_key, 'claim', 'allowed',
          CASE WHEN array_length(v_soft, 1) IS NULL THEN ARRAY['no_conflict'] ELSE v_soft END,
          COALESCE(p_founder_override, false), COALESCE(p_override_reason, ''), auth.uid());

  RETURN jsonb_build_object('decision', 'allowed', 'ownership_id', v_new_id,
    'reason_codes', CASE WHEN array_length(v_soft, 1) IS NULL THEN ARRAY['no_conflict'] ELSE v_soft END,
    'hard_blocked', false, 'founder_override_applied', COALESCE(p_founder_override, false) AND array_length(v_soft, 1) IS NOT NULL,
    'current_owner_business', p_business_name);
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_stale_ai_leases()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n int;
BEGIN
  UPDATE public.ai_concurrency_leases
     SET status='expired', released_at = now()
   WHERE status='active' AND expires_at < now();
  GET DIAGNOSTICS n = ROW_COUNT;

  IF n > 0 THEN
    INSERT INTO public.ai_runtime_events (event_type, severity, message, metadata)
    VALUES ('stale_lease_cleanup', 'warning',
            'Expired ' || n || ' stale AI concurrency lease(s)',
            jsonb_build_object('expired_count', n));
  END IF;

  RETURN n;
END;
$function$

CREATE OR REPLACE FUNCTION public.compare_system_versions(_version_a integer, _version_b integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_a record;
  v_b record;
  v_diff jsonb;
  v_added integer;
  v_removed integer;
  v_modified integer;
  v_id uuid;
BEGIN
  SELECT * INTO v_a FROM public.system_versions WHERE version_number = _version_a;
  SELECT * INTO v_b FROM public.system_versions WHERE version_number = _version_b;
  IF v_a.id IS NULL OR v_b.id IS NULL THEN
    RAISE EXCEPTION 'Version not found';
  END IF;

  v_diff := jsonb_build_object(
    'pages',         jsonb_build_object('a', v_a.pages_count,        'b', v_b.pages_count,        'delta', v_b.pages_count        - v_a.pages_count),
    'content',       jsonb_build_object('a', v_a.content_count,      'b', v_b.content_count,      'delta', v_b.content_count      - v_a.content_count),
    'backend',       jsonb_build_object('a', v_a.backend_count,      'b', v_b.backend_count,      'delta', v_b.backend_count      - v_a.backend_count),
    'workflows',     jsonb_build_object('a', v_a.workflow_count,     'b', v_b.workflow_count,     'delta', v_b.workflow_count     - v_a.workflow_count),
    'rules',         jsonb_build_object('a', v_a.rule_count,         'b', v_b.rule_count,         'delta', v_b.rule_count         - v_a.rule_count),
    'integrations',  jsonb_build_object('a', v_a.integration_count,  'b', v_b.integration_count,  'delta', v_b.integration_count  - v_a.integration_count),
    'data_flows',    jsonb_build_object('a', v_a.data_flow_count,    'b', v_b.data_flow_count,    'delta', v_b.data_flow_count    - v_a.data_flow_count),
    'coverage',      jsonb_build_object('a', v_a.coverage_score,     'b', v_b.coverage_score,     'delta', v_b.coverage_score     - v_a.coverage_score)
  );

  v_added := GREATEST(0, (v_b.pages_count - v_a.pages_count))
           + GREATEST(0, (v_b.backend_count - v_a.backend_count))
           + GREATEST(0, (v_b.workflow_count - v_a.workflow_count))
           + GREATEST(0, (v_b.rule_count - v_a.rule_count))
           + GREATEST(0, (v_b.integration_count - v_a.integration_count))
           + GREATEST(0, (v_b.data_flow_count - v_a.data_flow_count));

  v_removed := GREATEST(0, (v_a.pages_count - v_b.pages_count))
             + GREATEST(0, (v_a.backend_count - v_b.backend_count))
             + GREATEST(0, (v_a.workflow_count - v_b.workflow_count))
             + GREATEST(0, (v_a.rule_count - v_b.rule_count))
             + GREATEST(0, (v_a.integration_count - v_b.integration_count))
             + GREATEST(0, (v_a.data_flow_count - v_b.data_flow_count));

  v_modified := ABS(v_b.coverage_score - v_a.coverage_score);

  INSERT INTO public.system_version_diffs (version_a, version_b, diff_summary, added_count, removed_count, modified_count)
  VALUES (_version_a, _version_b, v_diff, v_added, v_removed, v_modified)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'diff_id', v_id,
    'version_a', _version_a,
    'version_b', _version_b,
    'added', v_added,
    'removed', v_removed,
    'modified', v_modified,
    'summary', v_diff
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.compliance_check_assignment(_assignment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  a public.assignments;
  s public.suppliers;
BEGIN
  SELECT * INTO a FROM public.assignments WHERE id = _assignment_id;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT * INTO s FROM public.suppliers WHERE id = a.supplier_id;

  -- Supplier not approved (defence in depth — guard already blocks in DB)
  IF s.status <> 'APPROVED' THEN
    PERFORM public.log_compliance_event(
      'delivery_supplier_not_approved','assignment', a.id, a.business_name, 'GLOBAL',
      'SUPPLIER_NOT_APPROVED',
      'Assignment created against non-approved supplier ' || s.email || ' (' || s.status || ')',
      '{}'::jsonb
    );
  END IF;

  -- Supplier vs client business mismatch (jurisdiction proxy)
  IF COALESCE(s.business_name,'') <> '' AND COALESCE(a.business_name,'') <> ''
     AND s.business_name <> a.business_name THEN
    PERFORM public.log_compliance_event(
      'delivery_jurisdiction_mismatch','assignment', a.id, a.business_name, 'GLOBAL',
      'JURISDICTION_MISMATCH',
      'Supplier business ' || s.business_name || ' ≠ assignment business ' || a.business_name,
      '{}'::jsonb
    );
  END IF;

  -- Missing SLA
  IF a.expected_completion_date IS NULL THEN
    PERFORM public.log_compliance_event(
      'delivery_sla_missing','assignment', a.id, a.business_name, 'GLOBAL',
      'SLA_MISSING',
      'Assignment created without expected_completion_date',
      '{}'::jsonb
    );
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.compliance_check_contact(_contact_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c public.contacts;
  resolved_country text;
  jp public.jurisdiction_profiles;
BEGIN
  SELECT * INTO c FROM public.contacts WHERE id = _contact_id;
  IF NOT FOUND THEN RETURN; END IF;
  resolved_country := public.resolve_entity_country(c.id, c.assigned_business);

  IF COALESCE(c.source,'') = '' THEN
    PERFORM public.log_compliance_event(
      'data_source_missing','contact', c.id, c.assigned_business, resolved_country,
      'PERSONAL_DATA_NO_SOURCE',
      'Contact ' || c.email || ' stored without recorded data source',
      '{}'::jsonb);
  END IF;

  SELECT * INTO jp FROM public.jurisdiction_profiles jp_inner
   WHERE jp_inner.country = resolved_country LIMIT 1;
  IF jp.gdpr_applicable IS TRUE AND COALESCE(c.assigned_business,'') NOT IN ('','UK','EU') THEN
    PERFORM public.log_compliance_event(
      'data_cross_border','contact', c.id, c.assigned_business, resolved_country,
      'CROSS_BORDER_TRANSFER',
      'Contact in GDPR jurisdiction (' || resolved_country || ') assigned to non-EU/UK business ' || c.assigned_business,
      '{}'::jsonb);
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.compliance_check_demo(_demo_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d public.demo_access;
BEGIN
  SELECT * INTO d FROM public.demo_access WHERE id = _demo_id;
  IF NOT FOUND THEN RETURN; END IF;

  -- Token length / weak token
  IF length(COALESCE(d.demo_token,'')) < 24 THEN
    PERFORM public.log_compliance_event(
      'demo_weak_token','demo', d.id, d.business_name, 'GLOBAL',
      'WEAK_DEMO_TOKEN',
      'Demo access created with token shorter than 24 chars',
      jsonb_build_object('token_length', length(COALESCE(d.demo_token,'')))
    );
  END IF;

  -- Expiry > 60 days
  IF d.expires_at > now() + interval '60 days' THEN
    PERFORM public.log_compliance_event(
      'demo_long_expiry','demo', d.id, d.business_name, 'GLOBAL',
      'DEMO_LONG_EXPIRY',
      'Demo expiry exceeds 60 days — exposure window risk',
      jsonb_build_object('expires_at', d.expires_at)
    );
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.compliance_check_invoice(_invoice_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  inv public.invoices;
  expected numeric;
BEGIN
  SELECT * INTO inv FROM public.invoices WHERE id = _invoice_id;
  IF NOT FOUND THEN RETURN; END IF;

  expected := COALESCE(inv.expected_amount, (COALESCE(inv.amount_min,0)+COALESCE(inv.amount_max,0))/2.0);

  IF inv.status IN ('OVERDUE','PARTIALLY_PAID')
     AND inv.due_date IS NOT NULL
     AND inv.due_date < CURRENT_DATE - interval '14 days' THEN
    PERFORM public.log_compliance_event(
      'finance_overdue_14d','invoice', inv.id, inv.business_name, 'GLOBAL',
      'INVOICE_OVERDUE_14D',
      'Invoice ' || inv.invoice_number || ' overdue >14 days',
      jsonb_build_object('due_date', inv.due_date, 'amount', expected)
    );
  END IF;

  IF expected >= 50000 THEN
    PERFORM public.log_compliance_event(
      'finance_large_value','invoice', inv.id, inv.business_name, 'GLOBAL',
      'LARGE_VALUE_INVOICE',
      'Invoice ' || inv.invoice_number || ' >= 50k — review threshold',
      jsonb_build_object('amount', expected)
    );
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.compliance_check_outbound_communication(_comm_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  comm public.communications;
  c public.contacts;
  jp public.jurisdiction_profiles;
  recent_count int;
  resolved_country text;
BEGIN
  SELECT * INTO comm FROM public.communications WHERE id = _comm_id;
  IF NOT FOUND OR comm.direction <> 'outbound' THEN RETURN; END IF;
  SELECT * INTO c FROM public.contacts WHERE id = comm.contact_id;
  IF NOT FOUND THEN RETURN; END IF;
  resolved_country := public.resolve_entity_country(c.id, c.assigned_business);
  SELECT * INTO jp FROM public.jurisdiction_profiles jp_inner
   WHERE jp_inner.country = resolved_country LIMIT 1;

  IF c.status = 'DO_NOT_CONTACT' THEN
    PERFORM public.log_compliance_event(
      'outreach_do_not_contact','message', comm.id, c.assigned_business, resolved_country,
      'DO_NOT_CONTACT_VIOLATION',
      'Outbound communication recorded against DO_NOT_CONTACT contact ' || c.email,
      jsonb_build_object('contact_id', c.id, 'channel', comm.channel));
  END IF;

  IF jp.consent_required IS TRUE THEN
    PERFORM public.log_compliance_event(
      'outreach_consent_required','message', comm.id, c.assigned_business, resolved_country,
      'CONSENT_NOT_RECORDED',
      'Outbound to ' || c.email || ' in ' || resolved_country || ' — consent flag not stored',
      jsonb_build_object('contact_id', c.id));
  END IF;

  SELECT COUNT(*) INTO recent_count FROM public.communications
   WHERE contact_id = c.id AND direction = 'outbound'
     AND timestamp > now() - interval '24 hours';
  IF recent_count > 5 THEN
    PERFORM public.log_compliance_event(
      'outreach_frequency_cap','contact', c.id, c.assigned_business, resolved_country,
      'FREQUENCY_CAP_EXCEEDED',
      'Contact ' || c.email || ' received ' || recent_count || ' outbound messages in 24h',
      jsonb_build_object('count_24h', recent_count));
  END IF;

  IF comm.channel = 'email' AND POSITION('unsubscribe' IN lower(COALESCE(comm.message,''))) = 0 THEN
    PERFORM public.log_compliance_event(
      'outreach_unsubscribe_missing','message', comm.id, c.assigned_business, resolved_country,
      'UNSUBSCRIBE_MISSING',
      'Outbound email to ' || c.email || ' missing unsubscribe language',
      '{}'::jsonb);
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.compliance_check_payment(_payment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p public.payments; inv public.invoices;
BEGIN
  SELECT * INTO p FROM public.payments WHERE id = _payment_id;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT * INTO inv FROM public.invoices WHERE id = p.invoice_id;
