CREATE OR REPLACE FUNCTION public.compliance_check_proposal(_proposal_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  p public.internal_proposals;
  has_template boolean;
BEGIN
  SELECT * INTO p FROM public.internal_proposals WHERE id = _proposal_id;
  IF NOT FOUND THEN RETURN; END IF;

  -- a) Missing "non-binding estimate" wording in scope/cost fields
  IF POSITION('non-binding' IN lower(
        COALESCE(p.estimated_cost_range,'') || ' ' ||
        COALESCE(p.estimated_scope,'')      || ' ' ||
        COALESCE(p.estimated_roi_summary,'')
      )) = 0 THEN
    PERFORM public.log_compliance_event(
      'proposal_non_binding_missing','proposal', p.id, p.business_name, 'GLOBAL',
      'NON_BINDING_LANGUAGE_MISSING',
      'Proposal ' || COALESCE(p.title,'') || ' missing non-binding estimate wording',
      '{}'::jsonb
    );
  END IF;

  -- b) Missing contract template for business
  SELECT EXISTS(
    SELECT 1 FROM public.contract_templates
     WHERE active = true
       AND (business_name = p.business_name OR business_name = '')
  ) INTO has_template;
  IF NOT has_template THEN
    PERFORM public.log_compliance_event(
      'proposal_template_missing','proposal', p.id, p.business_name, 'GLOBAL',
      'CONTRACT_TEMPLATE_MISSING',
      'No active contract template registered for business ' || COALESCE(p.business_name,'(unset)'),
      '{}'::jsonb
    );
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.compute_intent_score(_contact_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_replies int := 0; v_demo_uses int := 0; v_proposal_views int := 0;
  v_last_activity timestamptz; v_days_inactive int := 0; v_score int := 0;
BEGIN
  SELECT COUNT(*) INTO v_replies FROM public.email_events
   WHERE contact_id = _contact_id AND event_type = 'replied';
  SELECT COUNT(*) INTO v_demo_uses FROM public.demo_events de
    JOIN public.demo_access da ON da.id = de.demo_id
   WHERE da.contact_id = _contact_id AND de.event_type::text IN ('feature_used','session_start');
  SELECT COUNT(*) INTO v_proposal_views FROM public.internal_proposals
   WHERE contact_id = _contact_id AND viewed_at IS NOT NULL;
  IF v_replies > 0 THEN v_score := v_score + 30; END IF;
  IF v_replies > 1 THEN v_score := v_score + 20; END IF;
  IF v_demo_uses > 0 THEN v_score := v_score + 25; END IF;
  IF v_proposal_views > 0 THEN v_score := v_score + 15; END IF;
  SELECT GREATEST(
    COALESCE((SELECT MAX(timestamp) FROM public.email_events WHERE contact_id = _contact_id), 'epoch'::timestamptz),
    COALESCE((SELECT MAX(last_replied_at) FROM public.contacts WHERE id = _contact_id), 'epoch'::timestamptz)
  ) INTO v_last_activity;
  IF v_last_activity IS NOT NULL AND v_last_activity > 'epoch'::timestamptz THEN
    v_days_inactive := GREATEST(0, EXTRACT(DAY FROM (now() - v_last_activity))::int);
    v_score := v_score - (v_days_inactive * 5);
  END IF;
  v_score := GREATEST(0, LEAST(100, v_score));
  UPDATE public.contacts SET intent_score = v_score, updated_at = now() WHERE id = _contact_id;
  UPDATE public.conversations SET intent_score = v_score, updated_at = now() WHERE contact_id = _contact_id;
  RETURN v_score;
END; $function$

CREATE OR REPLACE FUNCTION public.crm_match_interaction_preview(p_interaction_id uuid DEFAULT NULL::uuid, p_provider_event_id uuid DEFAULT NULL::uuid, p_contact_email text DEFAULT NULL::text, p_provider_message_id text DEFAULT NULL::text, p_provider_campaign_id text DEFAULT NULL::text, p_business_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_email text := lower(trim(coalesce(p_contact_email, '')));
  v_provider_type text;
  v_external_event_id text;
  v_provider_msg text := p_provider_message_id;
  v_provider_camp text := p_provider_campaign_id;
  v_business_id uuid := p_business_id;
  v_interaction_type text;
  v_candidates jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_recommended jsonb := NULL;
  v_dedupe_key text := NULL;
  v_should_create_conv boolean := false;
  v_founder_review boolean := false;
  r record;
  v_confidence numeric;
BEGIN
  -- Authorization
  IF NOT (public.has_role(auth.uid(), 'founder'::app_role) OR public.has_role(auth.uid(), 'admin'::app_role)) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  -- Hydrate from ledger
  IF p_interaction_id IS NOT NULL THEN
    SELECT lower(trim(coalesce(contact_email, ''))), provider_type, provider_message_id, provider_campaign_id, external_event_id, interaction_type, business_id
    INTO v_email, v_provider_type, v_provider_msg, v_provider_camp, v_external_event_id, v_interaction_type, v_business_id
    FROM public.crm_interaction_ledger WHERE id = p_interaction_id;
  END IF;

  -- Hydrate from provider event
  IF p_provider_event_id IS NOT NULL THEN
    SELECT
      coalesce(v_provider_type, provider_type),
      coalesce(v_external_event_id, external_event_id),
      coalesce(v_provider_camp, provider_campaign_id),
      coalesce(v_provider_msg, provider_message_id),
      coalesce(NULLIF(v_email,''), lower(trim(coalesce(contact_email,''))))
    INTO v_provider_type, v_external_event_id, v_provider_camp, v_provider_msg, v_email
    FROM public.outbound_provider_events WHERE id = p_provider_event_id;
  END IF;

  -- 1. provider lead mapping
  IF v_provider_type IS NOT NULL AND v_provider_camp IS NOT NULL AND v_email <> '' THEN
    FOR r IN
      SELECT liftor_contact_id, business_id, liftor_campaign_id
      FROM public.outbound_provider_lead_mappings
      WHERE provider_type = v_provider_type
        AND provider_campaign_id = v_provider_camp
        AND lower(contact_email) = v_email
      LIMIT 3
    LOOP
      v_candidates := v_candidates || jsonb_build_object(
        'method','provider_lead_mapping','confidence',0.98,
        'contact_id',r.liftor_contact_id,'business_id',r.business_id,'campaign_id',r.liftor_campaign_id);
    END LOOP;
  END IF;

  -- 2. provider campaign mapping
  IF v_provider_type IS NOT NULL AND v_provider_camp IS NOT NULL THEN
    FOR r IN
      SELECT liftor_campaign_id, business_id
      FROM public.outbound_provider_campaign_mappings
      WHERE provider_type = v_provider_type
        AND provider_campaign_id = v_provider_camp
      LIMIT 3
    LOOP
      v_candidates := v_candidates || jsonb_build_object(
        'method','provider_campaign_mapping','confidence',0.7,
        'campaign_id',r.liftor_campaign_id,'business_id',r.business_id);
    END LOOP;
  END IF;

  -- 3. exact contact email
  IF v_email <> '' THEN
    FOR r IN
      SELECT id FROM public.contacts WHERE lower(trim(email)) = v_email LIMIT 5
    LOOP
      v_confidence := 0.9;
      v_candidates := v_candidates || jsonb_build_object(
        'method','contact_email_exact','confidence',v_confidence,'contact_id',r.id);
    END LOOP;
  END IF;

  -- 4. communication by provider_message_id
  IF v_provider_msg IS NOT NULL THEN
    FOR r IN
      SELECT c.id, c.contact_id
      FROM public.communications c
      WHERE c.message ILIKE '%' || v_provider_msg || '%'
      LIMIT 2
    LOOP
      v_candidates := v_candidates || jsonb_build_object(
        'method','communication_provider_message_id','confidence',0.6,
        'communication_id',r.id,'contact_id',r.contact_id);
    END LOOP;
  END IF;

  -- 5. email_events by provider_message_id
  IF v_provider_msg IS NOT NULL THEN
    BEGIN
      FOR r IN EXECUTE 'SELECT contact_id FROM public.email_events WHERE provider_message_id = $1 LIMIT 2' USING v_provider_msg
      LOOP
        v_candidates := v_candidates || jsonb_build_object(
          'method','email_event_provider_message_id','confidence',0.85,'contact_id',r.contact_id);
      END LOOP;
    EXCEPTION WHEN undefined_column OR undefined_table THEN
      NULL;
    END;
  END IF;

  -- 6. existing conversation by contact/business
  IF v_email <> '' THEN
    FOR r IN
      SELECT cv.id, cv.contact_id
      FROM public.conversations cv
      JOIN public.contacts ct ON ct.id = cv.contact_id
      WHERE lower(trim(ct.email)) = v_email
      ORDER BY cv.last_message_at DESC
      LIMIT 2
    LOOP
      v_candidates := v_candidates || jsonb_build_object(
        'method','conversation_by_contact','confidence',0.7,
        'conversation_id',r.id,'contact_id',r.contact_id);
    END LOOP;
  END IF;

  -- 7. BCR by contact/business
  IF v_email <> '' THEN
    FOR r IN
      SELECT bcr.id, bcr.contact_id, bcr.business_id
      FROM public.business_contact_relationships bcr
      JOIN public.contacts ct ON ct.id = bcr.contact_id
      WHERE lower(trim(ct.email)) = v_email
      LIMIT 3
    LOOP
      v_candidates := v_candidates || jsonb_build_object(
        'method','bcr_by_contact','confidence',0.6,
        'business_contact_relationship_id',r.id,'contact_id',r.contact_id,'business_id',r.business_id);
    END LOOP;
  END IF;

  -- 9. fallback by business_id
  IF v_business_id IS NOT NULL THEN
    v_candidates := v_candidates || jsonb_build_object(
      'method','business_only_fallback','confidence',0.2,'business_id',v_business_id);
  END IF;

  -- Recommended = highest confidence
  SELECT to_jsonb(c)
  INTO v_recommended
  FROM jsonb_array_elements(v_candidates) c
  ORDER BY (c->>'confidence')::numeric DESC NULLS LAST
  LIMIT 1;

  -- Warnings
  IF v_email = '' THEN
    v_warnings := v_warnings || to_jsonb('no_contact_email'::text);
  END IF;
  IF jsonb_array_length(v_candidates) = 0 THEN
    v_warnings := v_warnings || to_jsonb('no_candidates_found'::text);
    v_founder_review := true;
  END IF;
  IF jsonb_array_length(v_candidates) > 1 AND v_recommended IS NOT NULL
     AND (v_recommended->>'confidence')::numeric < 0.7 THEN
    v_founder_review := true;
  END IF;

  -- dedupe_key recommendation
  IF v_provider_type IS NOT NULL AND v_external_event_id IS NOT NULL THEN
    v_dedupe_key := v_provider_type || ':' || v_external_event_id;
  ELSIF v_provider_type IS NOT NULL AND v_provider_msg IS NOT NULL AND v_interaction_type IS NOT NULL THEN
    v_dedupe_key := v_provider_type || ':' || v_provider_msg || ':' || v_interaction_type;
  ELSIF v_email <> '' AND v_interaction_type IS NOT NULL THEN
    v_dedupe_key := 'email:' || v_email || ':' || v_interaction_type;
  END IF;

  -- should create conversation later
  IF v_recommended IS NOT NULL
     AND v_recommended ? 'contact_id'
     AND NOT (v_recommended ? 'conversation_id') THEN
    v_should_create_conv := true;
  END IF;

  RETURN jsonb_build_object(
    'candidates', v_candidates,
    'recommended', v_recommended,
    'confidence', COALESCE((v_recommended->>'confidence')::numeric, 0),
    'warnings', v_warnings,
    'dedupe_key', v_dedupe_key,
    'should_create_conversation_later', v_should_create_conv,
    'founder_review_required', v_founder_review,
    'inputs', jsonb_build_object(
      'contact_email', v_email,
      'provider_type', v_provider_type,
      'provider_campaign_id', v_provider_camp,
      'provider_message_id', v_provider_msg,
      'external_event_id', v_external_event_id,
      'business_id', v_business_id,
      'interaction_type', v_interaction_type
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.detect_orphan_content()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_orphans jsonb := '[]'::jsonb;
  v_count integer := 0;
  v_row record;
BEGIN
  FOR v_row IN
    SELECT c.id, c.page, c.content_type, c.linked_feature
    FROM public.system_content c
    LEFT JOIN public.system_pages_index p ON p.route_path = c.page
    WHERE p.id IS NULL
       OR c.linked_feature IS NULL
       OR c.linked_feature = ''
  LOOP
    v_count := v_count + 1;
    v_orphans := v_orphans || jsonb_build_object(
      'id', v_row.id, 'page', v_row.page,
      'type', v_row.content_type, 'linked_feature', v_row.linked_feature
    );
  END LOOP;

  IF v_count > 0 THEN
    INSERT INTO public.system_events (event_type, entity_type, severity, message, metadata)
    VALUES (
      'orphan_content_detected',
      'system_content',
      'medium',
      'Orphan content found: ' || v_count || ' entries unlinked',
      jsonb_build_object('orphans', v_orphans)
    );
  END IF;

  RETURN jsonb_build_object(
    'orphans_found', v_count,
    'details', v_orphans,
    'checked_at', now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.domain_for_inbox(_inbox_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  email_addr text; dom_name text; dom_id uuid;
BEGIN
  SELECT email_address INTO email_addr FROM public.inboxes WHERE id = _inbox_id;
  IF email_addr IS NULL OR position('@' in email_addr) = 0 THEN RETURN NULL; END IF;
  dom_name := split_part(email_addr, '@', 2);
  SELECT id INTO dom_id FROM public.sending_domains WHERE domain_name = dom_name;
  IF dom_id IS NULL THEN
    INSERT INTO public.sending_domains (domain_name) VALUES (dom_name) RETURNING id INTO dom_id;
  END IF;
  RETURN dom_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_founder_approval_for_warm_up_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.action_type IN (
    'draft_soft_relationship_email','draft_founder_positioning_note',
    'draft_partnership_angle','draft_buyer_thesis','mark_sale_conversation_ready'
  ) AND NEW.status = 'completed' AND NEW.founder_approved IS NOT TRUE THEN
    RAISE EXCEPTION 'Founder approval required before marking buyer-contact-style warm-up action completed';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_inbox_ramp(_inbox_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_inbox public.inboxes; v_age_days int; v_max int;
BEGIN
  SELECT * INTO v_inbox FROM public.inboxes WHERE id=_inbox_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('allowed', false, 'reason', 'INBOX_NOT_FOUND'); END IF;
  v_age_days := GREATEST(0, EXTRACT(EPOCH FROM (now() - v_inbox.warmup_started_at))::int / 86400);
  v_max := CASE WHEN v_age_days < 3 THEN 20 WHEN v_age_days < 7 THEN 40 ELSE 80 END;
  v_max := GREATEST(v_max, COALESCE(v_inbox.daily_send_limit, 0));
  IF v_inbox.current_send_count >= v_max THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'RAMP_LIMIT_REACHED',
                              'sent_today', v_inbox.current_send_count, 'max_today', v_max, 'age_days', v_age_days);
  END IF;
  RETURN jsonb_build_object('allowed', true, 'sent_today', v_inbox.current_send_count,
                            'max_today', v_max, 'age_days', v_age_days);
END;
$function$

CREATE OR REPLACE FUNCTION public.enrich_all_contacts()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; n int := 0;
BEGIN
  FOR r IN SELECT id FROM public.contacts WHERE enriched_at IS NULL LOOP
    PERFORM public.enrich_contact(r.id); n := n + 1;
  END LOOP;
  RETURN n;
END; $function$

CREATE OR REPLACE FUNCTION public.enrich_contact(_contact_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c public.contacts; v_industry text; v_size public.company_size_tier;
  v_sen public.seniority_level; v_li text; v_role text; pool_industry text[];
BEGIN
  SELECT * INTO c FROM public.contacts WHERE id = _contact_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason','not_found'); END IF;
  pool_industry := CASE c.assigned_business
    WHEN 'Liftor AI' THEN ARRAY['Technology','SaaS','Fintech','Consulting','AI Services']
    WHEN 'GloBlast' THEN ARRAY['Beauty','Cosmetics','Retail','E-commerce','Wellness']
    WHEN 'Health Access' THEN ARRAY['Healthcare','Medical Services','Pharma','BioTech','Public Health']
    ELSE ARRAY['Professional Services','Technology','Retail']
  END;
  v_industry := COALESCE(c.industry, pool_industry[1 + (abs(hashtext(c.id::text)) % array_length(pool_industry,1))]);
  v_size := COALESCE(c.company_size, (ARRAY['small','medium','large']::public.company_size_tier[])[1 + (abs(hashtext(c.id::text||'sz')) % 3)]);
  v_role := lower(COALESCE(c.role,''));
  v_sen := COALESCE(c.seniority,
    CASE
      WHEN v_role ~ '(ceo|cto|cfo|coo|chief|founder|owner|president)' THEN 'c-level'::public.seniority_level
      WHEN v_role ~ '(vp|director|head)' THEN 'director'::public.seniority_level
      WHEN v_role ~ '(manager|lead|principal)' THEN 'manager'::public.seniority_level
      WHEN v_role ~ '(junior|associate|assistant|intern)' THEN 'junior'::public.seniority_level
      ELSE (ARRAY['junior','manager','director','c-level']::public.seniority_level[])[1 + (abs(hashtext(c.id::text||'sn')) % 4)]
    END);
  v_li := COALESCE(c.linkedin_url,
    'https://linkedin.com/in/' || regexp_replace(lower(COALESCE(c.name,'lead')), '[^a-z0-9]+','-','g') || '-' || substr(c.id::text,1,6));
  UPDATE public.contacts SET company_size = v_size, industry = v_industry,
    linkedin_url = v_li, seniority = v_sen, enriched_at = now(), updated_at = now()
   WHERE id = _contact_id;
  RETURN jsonb_build_object('ok', true, 'industry', v_industry,
    'company_size', v_size, 'seniority', v_sen, 'linkedin_url', v_li);
END; $function$

CREATE OR REPLACE FUNCTION public.escalate_retry_failure(_retry_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.retry_queue;
BEGIN
  SELECT * INTO r FROM public.retry_queue WHERE id = _retry_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF r.retry_count >= 3 AND NOT r.escalated THEN
    PERFORM public.log_system_event(
      'retry_exhausted', r.entity_type, r.entity_id, r.business_name, 'critical',
      'Retry exhausted for ' || r.entity_type || ' ' || COALESCE(r.entity_id::text,'') || ': ' || COALESCE(r.last_error_message, r.last_error,''),
      jsonb_build_object('action_type', r.action_type, 'retries', r.retry_count, 'reason', r.retry_reason));
    UPDATE public.retry_queue SET escalated = true, status = 'failed', updated_at = now()
     WHERE id = _retry_id;
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.evaluate_ai_reply(_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  word_count int; has_cta boolean; has_repetition boolean;
  reasons text[] := ARRAY[]::text[]; pass boolean := true; lower_t text; repeated_word text;
BEGIN
  IF _text IS NULL OR length(trim(_text)) = 0 THEN
    RETURN jsonb_build_object('pass', false, 'reasons', ARRAY['empty']);
  END IF;
  word_count := array_length(regexp_split_to_array(trim(_text), '\s+'), 1);
  IF word_count > 120 THEN pass := false; reasons := reasons || 'too_long'; END IF;
  lower_t := lower(_text);
  has_cta := lower_t ~ '(book|schedule|reply|let me know|next step|chat|call|meeting|demo|introduce|connect|available|interested)';
  IF NOT has_cta THEN pass := false; reasons := reasons || 'missing_cta'; END IF;
  WITH words AS (
    SELECT lower(regexp_split_to_table(regexp_replace(_text,'[^a-zA-Z0-9 ]','','g'),'\s+')) AS w
  ), grams AS (
    SELECT string_agg(w, ' ') AS phrase
    FROM (SELECT w, row_number() OVER () rn FROM words) t
    GROUP BY (rn-1)/4
  )
  SELECT phrase INTO repeated_word FROM grams
  WHERE length(phrase) > 10 GROUP BY phrase HAVING COUNT(*) > 1 LIMIT 1;
  has_repetition := repeated_word IS NOT NULL;
  IF has_repetition THEN pass := false; reasons := reasons || 'repetition'; END IF;
  RETURN jsonb_build_object('pass', pass, 'word_count', word_count,
    'has_cta', has_cta, 'has_repetition', has_repetition, 'reasons', reasons);
END; $function$

CREATE OR REPLACE FUNCTION public.founder_confirm_assignment(_assignment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  a public.assignments;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'FORBIDDEN');
  END IF;

  SELECT * INTO a FROM public.assignments WHERE id = _assignment_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND');
  END IF;
  IF a.status <> 'completed' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_COMPLETED', 'status', a.status);
  END IF;
  IF a.completion_confirmed_by_founder THEN
    RETURN jsonb_build_object('ok', true, 'already_confirmed', true);
  END IF;

  UPDATE public.assignments
     SET completion_confirmed_by_founder = true,
         confirmed_at = now(),
         requires_finance_action = true,
         updated_at = now()
   WHERE id = _assignment_id;

  INSERT INTO public.activity_log (event_type, description, entity_type, entity_id)
  VALUES ('assignment_ready_for_billing',
          'Assignment ' || _assignment_id::text || ' confirmed complete by founder — finance action required',
          'assignment', _assignment_id);

  RETURN jsonb_build_object('ok', true, 'assignment_id', _assignment_id);
END; $function$

CREATE OR REPLACE FUNCTION public.generate_invoice_number()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  year_part text := to_char(now(), 'YYYY');
  seq_part text;
  count_this_year integer;
BEGIN
  SELECT COUNT(*) + 1 INTO count_this_year
    FROM public.invoices
   WHERE issued_date >= date_trunc('year', now());
  seq_part := lpad(count_this_year::text, 5, '0');
  RETURN 'INV-' || year_part || '-' || seq_part;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_system_tasks_from_priority(_entity_type priority_entity_type, _entity_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ps public.priority_scores;
  csc int := 0;
  bn text := '';
BEGIN
  SELECT * INTO ps FROM public.priority_scores
   WHERE entity_type = _entity_type AND entity_id = _entity_id;
  IF NOT FOUND THEN RETURN; END IF;
  bn := COALESCE(ps.business_name,'');

  IF _entity_type = 'assignment' THEN
    IF EXISTS (SELECT 1 FROM public.assignments
                WHERE id = _entity_id
                  AND sla_status::text IN ('at_risk','overdue')
                  AND status::text NOT IN ('completed','failed')) THEN
      INSERT INTO public.system_tasks (entity_type, entity_id, business_name, task_type, priority_score, reason)
      VALUES (_entity_type, _entity_id, bn, 'review', ps.score, 'Assignment SLA at risk or overdue')
      ON CONFLICT DO NOTHING;
    END IF;
  END IF;

  IF _entity_type = 'deal' THEN
    IF EXISTS (
      SELECT 1 FROM public.internal_proposals ip
       WHERE ip.deal_id = _entity_id
         AND ip.status::text = 'viewed'
         AND ip.viewed_at IS NOT NULL
         AND ip.viewed_at < now() - interval '24 hours'
         AND ip.follow_up_completed_at IS NULL
    ) THEN
      INSERT INTO public.system_tasks (entity_type, entity_id, business_name, task_type, priority_score, reason)
      VALUES (_entity_type, _entity_id, bn, 'follow_up', ps.score, 'Proposal viewed >24h ago, no follow-up')
      ON CONFLICT DO NOTHING;
    END IF;
  END IF;

  csc := public.compliance_score_for(_entity_type::text, _entity_id);
  IF csc > 70 THEN
    INSERT INTO public.system_tasks (entity_type, entity_id, business_name, task_type, priority_score, reason)
    VALUES (_entity_type, _entity_id, bn, 'escalate', ps.score,
            'Compliance score ' || csc || ' exceeds 70 — review required')
    ON CONFLICT DO NOTHING;
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.get_crm_contact_360_summary(p_contact_id uuid, p_business_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contact jsonb;
  v_bcr jsonb;
  v_compliance jsonb;
  v_latest jsonb;
  v_comm jsonb;
  v_proposal_count int;
  v_demo_count int;
  v_deal_count int;
  v_invoice_count int;
  v_payment_count int;
  v_open_conversations int;
  v_risk jsonb := '[]'::jsonb;
  v_next text;
  v_score int := 0;
  v_business_names text[];
BEGIN
  IF NOT (public.has_role(auth.uid(), 'founder'::app_role) OR public.has_role(auth.uid(), 'admin'::app_role)) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT to_jsonb(c) INTO v_contact FROM public.contacts c WHERE c.id = p_contact_id;
  IF v_contact IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'contact_not_found');
  END IF;

  SELECT array_agg(business_name) INTO v_business_names
  FROM public.business_contact_relationships
  WHERE contact_id = p_contact_id
    AND (p_business_id IS NULL OR business_id = p_business_id);

  SELECT COALESCE(jsonb_agg(to_jsonb(b)), '[]'::jsonb) INTO v_bcr
  FROM (
    SELECT * FROM public.business_contact_relationships
    WHERE contact_id = p_contact_id
      AND (p_business_id IS NULL OR business_id = p_business_id)
    ORDER BY updated_at DESC
  ) b;

  SELECT jsonb_build_object(
    'open_count', COUNT(*) FILTER (WHERE NOT resolved),
    'high_critical_open', COUNT(*) FILTER (WHERE NOT resolved AND severity::text IN ('high','critical')),
    'last_event_at', MAX(created_at)
  ) INTO v_compliance
  FROM public.compliance_events
  WHERE (entity_type::text='contact' AND entity_id = p_contact_id)
     OR (business_name = ANY(COALESCE(v_business_names,'{}')));

  SELECT to_jsonb(t) INTO v_latest FROM (
    SELECT * FROM public.get_crm_contact_timeline(p_contact_id, p_business_id, 1) LIMIT 1
  ) t;

  SELECT jsonb_build_object(
    'last_inbound_at', MAX(c."timestamp") FILTER (WHERE c.direction='inbound'::communication_direction),
    'last_outbound_at', MAX(c."timestamp") FILTER (WHERE c.direction='outbound'::communication_direction),
    'last_ai_at', MAX(c."timestamp") FILTER (WHERE c.ai_generated)
  ) INTO v_comm
  FROM public.communications c WHERE c.contact_id = p_contact_id;

  SELECT count(*) INTO v_proposal_count FROM public.internal_proposals WHERE contact_id = p_contact_id;
  SELECT count(*) INTO v_demo_count FROM public.demo_access WHERE contact_id = p_contact_id;
  SELECT count(*) INTO v_deal_count FROM public.deals
   WHERE contact_id = p_contact_id OR business_name = ANY(COALESCE(v_business_names,'{}'));
  SELECT count(*) INTO v_invoice_count FROM public.invoices
   WHERE contact_id = p_contact_id OR business_name = ANY(COALESCE(v_business_names,'{}'));
  SELECT count(*) INTO v_payment_count FROM public.payments py
   JOIN public.invoices i ON i.id = py.invoice_id
   WHERE i.contact_id = p_contact_id OR py.business_name = ANY(COALESCE(v_business_names,'{}'));
  SELECT count(*) INTO v_open_conversations FROM public.conversations
   WHERE contact_id = p_contact_id AND status::text='OPEN';

  IF (v_compliance->>'high_critical_open')::int > 0 THEN
    v_risk := v_risk || to_jsonb('compliance_open_high_critical'::text);
  END IF;
  IF EXISTS (SELECT 1 FROM public.business_contact_relationships
              WHERE contact_id = p_contact_id AND do_not_contact = true) THEN
    v_risk := v_risk || to_jsonb('do_not_contact'::text);
  END IF;

  IF (v_compliance->>'high_critical_open')::int > 0 THEN
    v_next := 'Resolve open high/critical compliance events before any outreach';
  ELSIF v_open_conversations > 0 THEN
    v_next := 'Review open conversation and decide on next reply';
  ELSIF v_demo_count > 0 AND v_deal_count = 0 THEN
    v_next := 'Move demo viewer into a deal record';
  ELSIF v_proposal_count > 0 AND v_payment_count = 0 THEN
    v_next := 'Follow up on outstanding proposal / invoice';
  ELSE
    v_next := 'Capture latest interaction into ledger and assess intent';
  END IF;

  v_score := LEAST(100,
    (CASE WHEN v_contact->>'email' <> '' THEN 20 ELSE 0 END)
    + (CASE WHEN v_bcr <> '[]'::jsonb THEN 20 ELSE 0 END)
    + (CASE WHEN v_latest IS NOT NULL THEN 20 ELSE 0 END)
    + (CASE WHEN COALESCE((v_compliance->>'high_critical_open')::int,0) = 0 THEN 20 ELSE 0 END)
    + (CASE WHEN v_open_conversations > 0 OR v_proposal_count > 0 OR v_deal_count > 0 THEN 20 ELSE 0 END)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'contact', v_contact,
    'business_relationships', v_bcr,
    'business_names', COALESCE(to_jsonb(v_business_names), '[]'::jsonb),
    'compliance_state', COALESCE(v_compliance, '{}'::jsonb),
    'latest_interaction', v_latest,
    'latest_inbound', jsonb_build_object('last_inbound_at', v_comm->'last_inbound_at'),
    'latest_outbound', jsonb_build_object('last_outbound_at', v_comm->'last_outbound_at'),
    'latest_ai', jsonb_build_object('last_ai_at', v_comm->'last_ai_at'),
    'proposal_count', v_proposal_count,
    'demo_count', v_demo_count,
    'deal_count', v_deal_count,
    'invoice_count', v_invoice_count,
    'payment_count', v_payment_count,
    'open_conversations', v_open_conversations,
    'risk_flags', v_risk,
    'next_recommended_action', v_next,
    'timeline_readiness_score', v_score,
    'safety', jsonb_build_object('read_only', true, 'no_writes', true, 'no_send', true)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_crm_interaction_ledger_summary(p_business_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total INT;
  v_matched INT;
  v_unmatched INT;
  v_last7 INT;
  v_review INT;
  v_ai INT;
  v_compliance INT;
  v_dupes INT;
  v_by_source JSONB;
  v_by_type JSONB;
BEGIN
  IF NOT (public.has_role(auth.uid(),'founder') OR public.has_role(auth.uid(),'admin') OR auth.role() = 'service_role') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;

  SELECT count(*) INTO v_total FROM public.crm_interaction_ledger l
    WHERE p_business_id IS NULL OR l.business_id = p_business_id;
  SELECT count(*) INTO v_matched FROM public.crm_interaction_ledger l
    WHERE (p_business_id IS NULL OR l.business_id = p_business_id) AND matched_status = 'matched';
  SELECT count(*) INTO v_unmatched FROM public.crm_interaction_ledger l
    WHERE (p_business_id IS NULL OR l.business_id = p_business_id) AND matched_status <> 'matched';
  SELECT count(*) INTO v_last7 FROM public.crm_interaction_ledger l
    WHERE (p_business_id IS NULL OR l.business_id = p_business_id) AND occurred_at > now() - interval '7 days';
  SELECT count(*) INTO v_review FROM public.crm_interaction_ledger l
    WHERE (p_business_id IS NULL OR l.business_id = p_business_id) AND founder_review_required = true;
  SELECT count(*) INTO v_ai FROM public.crm_interaction_ledger l
    WHERE (p_business_id IS NULL OR l.business_id = p_business_id) AND ai_relevant = true;
  SELECT count(*) INTO v_compliance FROM public.crm_interaction_ledger l
    WHERE (p_business_id IS NULL OR l.business_id = p_business_id) AND compliance_relevant = true;

  SELECT coalesce(jsonb_object_agg(source_system, c), '{}'::jsonb) INTO v_by_source FROM (
    SELECT source_system, count(*)::int AS c FROM public.crm_interaction_ledger l
      WHERE (p_business_id IS NULL OR l.business_id = p_business_id)
      GROUP BY source_system
  ) x;
  SELECT coalesce(jsonb_object_agg(interaction_type, c), '{}'::jsonb) INTO v_by_type FROM (
    SELECT interaction_type, count(*)::int AS c FROM public.crm_interaction_ledger l
      WHERE (p_business_id IS NULL OR l.business_id = p_business_id)
      GROUP BY interaction_type
  ) y;

  SELECT count(*) INTO v_dupes FROM (
    SELECT dedupe_key FROM public.crm_interaction_ledger
      WHERE dedupe_key IS NOT NULL
      GROUP BY dedupe_key HAVING count(*) > 1
  ) d;

  RETURN jsonb_build_object(
    'ok', true,
    'total_interactions', v_total,
    'matched_interactions', v_matched,
    'unmatched_interactions', v_unmatched,
    'interactions_last_7_days', v_last7,
    'interactions_by_source_system', v_by_source,
    'interactions_by_type', v_by_type,
    'interactions_requiring_founder_review', v_review,
    'ai_relevant_interactions', v_ai,
    'compliance_relevant_interactions', v_compliance,
    'duplicate_dedupe_conflicts', v_dupes,
    'ledger_ready', true
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_crm_relationship_timeline(p_business_contact_relationship_id uuid, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contact uuid;
  v_business uuid;
  v_rows jsonb;
BEGIN
