CREATE OR REPLACE FUNCTION public.handle_deal_won()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'WON' AND (OLD.status IS NULL OR OLD.status <> 'WON') THEN
    -- Invoicing gate
    IF public.is_feature_enabled('invoicing', NEW.business_name) THEN
      INSERT INTO public.invoices (
        deal_id, contact_id, business_name, invoice_number,
        amount_min, amount_max, currency, status
      )
      VALUES (
        NEW.id, NEW.contact_id, NEW.business_name,
        'INV-' || to_char(now(), 'YYYYMMDD') || '-' || substr(NEW.id::text, 1, 8),
        NEW.estimated_value_min, NEW.estimated_value_max,
        NEW.currency, 'DRAFT'
      );
    ELSE
      PERFORM public.log_feature_skip('invoicing', NEW.business_name, 'deal', NEW.id);
    END IF;

    -- Lock contact as CLIENT (always)
    IF NEW.contact_id IS NOT NULL THEN
      UPDATE public.contacts SET status = 'CLIENT' WHERE id = NEW.contact_id;
    END IF;

    -- Supplier auto-assign gate (handled by separate trg_deal_won_auto_assign trigger;
    -- here we only log the skip when suppliers are disabled)
    IF NOT public.is_feature_enabled('suppliers', NEW.business_name) THEN
      PERFORM public.log_feature_skip('suppliers', NEW.business_name, 'deal', NEW.id);
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_payment_received()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  inv public.invoices%ROWTYPE;
  total_paid numeric;
  expected numeric;
  new_status public.invoice_status;
BEGIN
  INSERT INTO public.payment_events (invoice_id, event_type, details)
  VALUES (NEW.invoice_id, 'payment_received',
          'Payment of ' || NEW.amount_received::text || ' received via ' || NEW.method::text);

  SELECT * INTO inv FROM public.invoices WHERE id = NEW.invoice_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  SELECT COALESCE(SUM(amount_received), 0) INTO total_paid
    FROM public.payments WHERE invoice_id = NEW.invoice_id;

  expected := COALESCE(inv.expected_amount,
                       (COALESCE(inv.amount_min,0) + COALESCE(inv.amount_max,0)) / 2.0);

  IF expected > 0 AND total_paid >= expected THEN
    new_status := 'PAID';
  ELSIF total_paid > 0 AND total_paid < expected THEN
    new_status := 'PARTIALLY_PAID';
  ELSE
    new_status := inv.status;
  END IF;

  IF new_status <> inv.status THEN
    UPDATE public.invoices SET status = new_status, payment_risk_flag = CASE WHEN new_status = 'PAID' THEN false ELSE payment_risk_flag END
     WHERE id = NEW.invoice_id;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_supplier_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;

  IF NEW.status = 'APPROVED' AND OLD.status <> 'APPROVED' THEN
    NEW.approved_at := COALESCE(NEW.approved_at, now());
    UPDATE public.supplier_pipeline
       SET stage = 'approved', updated_at = now()
     WHERE supplier_id = NEW.id;
    INSERT INTO public.activity_log (event_type, description, entity_type, entity_id)
    VALUES ('supplier_approved', 'Supplier approved: ' || COALESCE(NEW.name, NEW.email), 'supplier', NEW.id);

  ELSIF NEW.status = 'REJECTED' AND OLD.status <> 'REJECTED' THEN
    NEW.rejected_at := COALESCE(NEW.rejected_at, now());
    UPDATE public.supplier_pipeline
       SET stage = 'rejected', updated_at = now()
     WHERE supplier_id = NEW.id;
    INSERT INTO public.activity_log (event_type, description, entity_type, entity_id)
    VALUES ('supplier_rejected', 'Supplier rejected: ' || COALESCE(NEW.name, NEW.email), 'supplier', NEW.id);

  ELSIF NEW.status = 'CONTACTED' AND OLD.status = 'NEW' THEN
    UPDATE public.supplier_pipeline
       SET stage = 'contacted', updated_at = now()
     WHERE supplier_id = NEW.id AND stage IN ('sourced');

  ELSIF NEW.status = 'QUALIFIED' THEN
    UPDATE public.supplier_pipeline
       SET stage = 'evaluated', updated_at = now()
     WHERE supplier_id = NEW.id AND stage NOT IN ('approved','rejected');
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.inbox_warmup_limit(_inbox_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ib public.inboxes;
  days_in int;
  warmup_max int;
BEGIN
  SELECT * INTO ib FROM public.inboxes WHERE id = _inbox_id;
  IF NOT FOUND THEN RETURN 0; END IF;
  days_in := GREATEST(0, EXTRACT(DAY FROM (now() - ib.warmup_started_at))::int);
  warmup_max := CASE
    WHEN days_in <  3 THEN 10
    WHEN days_in <  7 THEN 25
    WHEN days_in < 14 THEN 50
    ELSE ib.daily_send_limit
  END;
  -- Reputation throttling
  IF ib.reputation_score < 20 THEN RETURN 0; END IF;
  IF ib.reputation_score < 40 THEN RETURN GREATEST(1, warmup_max / 2); END IF;
  RETURN warmup_max;
END;
$function$

CREATE OR REPLACE FUNCTION public.is_feature_enabled(_feature_name text, _business_name text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _mode_id uuid;
  _enabled boolean;
BEGIN
  _mode_id := public.get_active_execution_mode(_business_name);
  IF _mode_id IS NULL THEN
    RETURN true; -- fallback: no mode configured → keep existing behaviour
  END IF;
  SELECT enabled INTO _enabled
    FROM public.system_feature_flags
   WHERE execution_mode_id = _mode_id AND feature_name = _feature_name
   LIMIT 1;
  RETURN COALESCE(_enabled, true);
END;
$function$

