DECLARE picked_id uuid; next_pos integer;
BEGIN
  SELECT id INTO picked_id FROM public.inboxes
   WHERE business_name = _business_name AND active = true
     AND reputation_score >= 20 AND current_send_count < daily_send_limit
   ORDER BY performance_score DESC, reputation_score DESC,
            last_used_sequence_position ASC, current_send_count ASC
   LIMIT 1;
  IF picked_id IS NULL THEN RETURN NULL; END IF;
  SELECT COALESCE(MAX(last_used_sequence_position), 0) + 1 INTO next_pos
  FROM public.inboxes WHERE business_name = _business_name;
  UPDATE public.inboxes SET last_used_sequence_position = next_pos WHERE id = picked_id;
  RETURN picked_id;
END; $function$

CREATE OR REPLACE FUNCTION public.priority_score_assignment(_assignment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  a public.assignments;
  d public.deals;
  revenue_f numeric := 0; prob_f numeric := 60; urgency_f numeric := 0;
  engagement_f numeric := 0; risk_f numeric := 0;
  raw numeric := 0; final_score int := 0; mid numeric := 0;
  days_to_due int; factors jsonb;
BEGIN
  SELECT * INTO a FROM public.assignments WHERE id = _assignment_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF a.status::text = 'failed' THEN
    INSERT INTO public.priority_scores (entity_type, entity_id, business_name, score, factors, priority_level, last_updated)
    VALUES ('assignment', _assignment_id, COALESCE(a.business_name,''), 95,
            jsonb_build_object('reason','assignment_failed','status', a.status::text),
            'critical'::priority_level, now())
    ON CONFLICT (entity_type, entity_id) DO UPDATE
      SET score = EXCLUDED.score, factors = EXCLUDED.factors,
          priority_level = EXCLUDED.priority_level, last_updated = now();
    RETURN;
  END IF;
  IF a.status::text = 'completed' THEN
    DELETE FROM public.priority_scores WHERE entity_type = 'assignment' AND entity_id = _assignment_id;
    RETURN;
  END IF;
  SELECT * INTO d FROM public.deals WHERE id = a.deal_id;
  mid := (COALESCE(d.estimated_value_min,0) + COALESCE(d.estimated_value_max,0)) / 2.0;
  revenue_f := LEAST(100, mid / 1000.0);
  IF a.expected_completion_date IS NOT NULL THEN
    days_to_due := (a.expected_completion_date - CURRENT_DATE);
    urgency_f := CASE
      WHEN days_to_due < 0 THEN 100
      WHEN days_to_due <= 1 THEN 90
      WHEN days_to_due <= 3 THEN 70
      WHEN days_to_due <= 7 THEN 40
      ELSE 20 END;
  ELSE urgency_f := 50;
  END IF;
  IF a.sla_status::text = 'overdue' THEN urgency_f := 100;
  ELSIF a.sla_status::text = 'at_risk' THEN urgency_f := GREATEST(urgency_f, 80);
  END IF;
  IF a.status::text = 'in_progress' THEN engagement_f := 70;
  ELSIF a.acknowledged_at IS NOT NULL THEN engagement_f := 50;
  ELSE engagement_f := 20;
  END IF;
  risk_f := public.compliance_score_for('assignment', _assignment_id);
  raw := (revenue_f * 0.30) + (prob_f * 0.25) + (urgency_f * 0.20) + (engagement_f * 0.15) - (risk_f * 0.10);
  final_score := GREATEST(0, LEAST(100, ROUND(raw)::int));
  IF a.sla_status::text = 'overdue' AND mid >= 25000 THEN
    final_score := GREATEST(final_score, 90);
  END IF;
  IF mid >= 100000 AND a.status::text <> 'completed' THEN
    final_score := GREATEST(final_score, 85);
  END IF;
  factors := jsonb_build_object(
    'revenue', ROUND(revenue_f,1), 'probability', ROUND(prob_f,1),
    'urgency', ROUND(urgency_f,1), 'engagement', ROUND(engagement_f,1),
    'risk', ROUND(risk_f,1), 'sla_status', a.sla_status::text,
    'status', a.status::text, 'mid_value', mid,
    'acknowledged', a.acknowledged_at IS NOT NULL);
  INSERT INTO public.priority_scores (entity_type, entity_id, business_name, score, factors, priority_level, last_updated)
  VALUES ('assignment', _assignment_id, COALESCE(a.business_name,''), final_score, factors,
          public.priority_level_from_score(final_score), now())
  ON CONFLICT (entity_type, entity_id) DO UPDATE
    SET score = EXCLUDED.score, factors = EXCLUDED.factors,
        priority_level = EXCLUDED.priority_level,
        business_name = EXCLUDED.business_name, last_updated = now();
END; $function$

CREATE OR REPLACE FUNCTION public.priority_score_contact(_contact_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c public.contacts; open_deal_value numeric := 0; revenue_f numeric := 0;
  prob_f numeric := 30; urgency_f numeric := 0; engagement_f numeric := 0;
  risk_f numeric := 0; raw numeric := 0; final_score int := 0;
  hours_since_reply int; demo_uses int := 0; factors jsonb;
BEGIN
  SELECT * INTO c FROM public.contacts WHERE id = _contact_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF c.status::text IN ('CLIENT','DO_NOT_CONTACT','SUPPLIER') THEN
    DELETE FROM public.priority_scores WHERE entity_type = 'contact' AND entity_id = _contact_id;
    RETURN;
  END IF;
  SELECT COALESCE(MAX((estimated_value_min + estimated_value_max)/2.0), 0)
    INTO open_deal_value FROM public.deals
   WHERE contact_id = _contact_id AND status::text NOT IN ('WON','LOST');
  revenue_f := LEAST(100, open_deal_value / 1000.0);
  prob_f := CASE c.status::text
    WHEN 'QUALIFIED' THEN 70 WHEN 'ENGAGED' THEN 50
    WHEN 'CONTACTED' THEN 30 WHEN 'NEW' THEN 20 ELSE 10 END;
  IF c.last_replied_at IS NOT NULL THEN
    hours_since_reply := EXTRACT(EPOCH FROM (now() - c.last_replied_at)) / 3600;
    urgency_f := CASE
      WHEN hours_since_reply <= 4 THEN 95 WHEN hours_since_reply <= 24 THEN 75
      WHEN hours_since_reply <= 72 THEN 50 ELSE 25 END;
  ELSE urgency_f := 20; END IF;
  SELECT COUNT(*) INTO demo_uses FROM public.demo_events de
    JOIN public.demo_access da ON da.id = de.demo_id
   WHERE da.contact_id = _contact_id AND de.timestamp > now() - interval '14 days';
  engagement_f := LEAST(100,
    (demo_uses * 10) + (CASE WHEN c.conversation_active THEN 20 ELSE 0 END)
    + (COALESCE(c.intent_score, 0) * 0.7));
  risk_f := public.compliance_score_for('contact', _contact_id);
  raw := (revenue_f * 0.30) + (prob_f * 0.20) + (urgency_f * 0.20)
       + (engagement_f * 0.20) - (risk_f * 0.10);
  final_score := GREATEST(0, LEAST(100, ROUND(raw)::int));
  factors := jsonb_build_object(
    'revenue', ROUND(revenue_f,1), 'probability', ROUND(prob_f,1),
    'urgency', ROUND(urgency_f,1), 'engagement', ROUND(engagement_f,1),
    'risk', ROUND(risk_f,1), 'open_deal_value', open_deal_value,
    'demo_uses_14d', demo_uses, 'intent_score', COALESCE(c.intent_score,0),
    'conversation_active', c.conversation_active, 'status', c.status::text);
  INSERT INTO public.priority_scores (entity_type, entity_id, business_name, score, factors, priority_level, last_updated)
  VALUES ('contact', _contact_id, COALESCE(c.assigned_business,''), final_score, factors,
          public.priority_level_from_score(final_score), now())
  ON CONFLICT (entity_type, entity_id) DO UPDATE
    SET score = EXCLUDED.score, factors = EXCLUDED.factors,
        priority_level = EXCLUDED.priority_level,
        business_name = EXCLUDED.business_name, last_updated = now();
END; $function$

CREATE OR REPLACE FUNCTION public.priority_score_conversation(_conversation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  conv public.conversations;
  revenue_f numeric := 0;
  prob_f numeric := 40;
  urgency_f numeric := 0;
  engagement_f numeric := 0;
  risk_f numeric := 0;
  raw numeric := 0;
  final_score int := 0;
  hours_since int;
  open_deal_value numeric := 0;
  factors jsonb;
BEGIN
  SELECT * INTO conv FROM public.conversations WHERE id = _conversation_id;
  IF NOT FOUND THEN RETURN; END IF;

  IF conv.status::text NOT IN ('OPEN','open','PENDING') THEN
    DELETE FROM public.priority_scores WHERE entity_type = 'conversation' AND entity_id = _conversation_id;
    RETURN;
  END IF;

  SELECT COALESCE(MAX((estimated_value_min + estimated_value_max)/2.0), 0)
    INTO open_deal_value
    FROM public.deals WHERE contact_id = conv.contact_id AND status::text NOT IN ('WON','LOST');
  revenue_f := LEAST(100, open_deal_value / 1000.0);

  hours_since := EXTRACT(EPOCH FROM (now() - conv.last_message_at)) / 3600;
  urgency_f := CASE
    WHEN hours_since <= 2 THEN 95
    WHEN hours_since <= 24 THEN 70
    WHEN hours_since <= 72 THEN 35
    ELSE 5 END;

  engagement_f := LEAST(100, 40 + COALESCE(conv.priority_boost,0) * 10);

  risk_f := public.compliance_score_for('contact', conv.contact_id);

  raw := (revenue_f * 0.30) + (prob_f * 0.25) + (urgency_f * 0.20)
       + (engagement_f * 0.15) - (risk_f * 0.10);
  final_score := GREATEST(0, LEAST(100, ROUND(raw)::int));

  factors := jsonb_build_object(
    'revenue', ROUND(revenue_f,1),
    'probability', ROUND(prob_f,1),
    'urgency', ROUND(urgency_f,1),
    'engagement', ROUND(engagement_f,1),
    'risk', ROUND(risk_f,1),
    'hours_since_last_message', hours_since,
    'priority_boost', COALESCE(conv.priority_boost,0),
    'last_intent', conv.last_intent
  );

  INSERT INTO public.priority_scores (entity_type, entity_id, business_name, score, factors, priority_level, last_updated)
  VALUES ('conversation', _conversation_id, COALESCE(conv.business_name,''), final_score, factors,
          public.priority_level_from_score(final_score), now())
  ON CONFLICT (entity_type, entity_id) DO UPDATE
    SET score = EXCLUDED.score, factors = EXCLUDED.factors,
        priority_level = EXCLUDED.priority_level,
        business_name = EXCLUDED.business_name, last_updated = now();
END; $function$

CREATE OR REPLACE FUNCTION public.priority_score_deal(_deal_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  d public.deals;
  mid numeric := 0;
  revenue_f numeric := 0; prob_f numeric := 0; urgency_f numeric := 0;
  engagement_f numeric := 0; risk_f numeric := 0;
  days_idle int := 0;
  has_invoice_overdue boolean := false;
  demo_uses int := 0;
  raw numeric := 0; final_score int := 0;
  factors jsonb;
BEGIN
  SELECT * INTO d FROM public.deals WHERE id = _deal_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF d.status::text IN ('WON','LOST') THEN
    DELETE FROM public.priority_scores WHERE entity_type = 'deal' AND entity_id = _deal_id;
    RETURN;
  END IF;
  mid := (COALESCE(d.estimated_value_min,0) + COALESCE(d.estimated_value_max,0)) / 2.0;
  revenue_f := LEAST(100, (mid / 1000.0));
  prob_f := COALESCE(d.probability, 0);
  IF d.status::text = 'QUALIFIED' THEN prob_f := prob_f + 15; END IF;
  IF d.status::text = 'PROPOSAL_SENT' THEN prob_f := prob_f + 25; END IF;
  IF prob_f > 100 THEN prob_f := 100; END IF;
  days_idle := EXTRACT(EPOCH FROM (now() - d.updated_at)) / 86400;
  urgency_f := LEAST(100, days_idle * 8);
  SELECT EXISTS(SELECT 1 FROM public.invoices WHERE deal_id = _deal_id AND status = 'OVERDUE')
    INTO has_invoice_overdue;
  IF has_invoice_overdue THEN urgency_f := LEAST(100, urgency_f + 30); END IF;
  IF d.contact_id IS NOT NULL THEN
    SELECT COUNT(*) INTO demo_uses FROM public.demo_events de
      JOIN public.demo_access da ON da.id = de.demo_id
     WHERE da.contact_id = d.contact_id AND de.timestamp > now() - interval '14 days';
    engagement_f := LEAST(100, demo_uses * 12);
    risk_f := public.compliance_score_for('contact', d.contact_id);
  END IF;
  raw := (revenue_f * 0.30) + (prob_f * 0.25) + (urgency_f * 0.20) + (engagement_f * 0.15) - (risk_f * 0.10);
  final_score := GREATEST(0, LEAST(100, ROUND(raw)::int));
  IF mid >= 100000 THEN final_score := GREATEST(final_score, 85); END IF;
  IF has_invoice_overdue AND mid >= 25000 THEN final_score := GREATEST(final_score, 90); END IF;
  IF has_invoice_overdue AND days_idle > 14 THEN final_score := GREATEST(final_score, 95); END IF;
  factors := jsonb_build_object(
    'revenue', ROUND(revenue_f,1), 'probability', ROUND(prob_f,1),
    'urgency', ROUND(urgency_f,1), 'engagement', ROUND(engagement_f,1),
    'risk', ROUND(risk_f,1), 'mid_value', mid, 'days_idle', days_idle,
    'demo_uses_14d', demo_uses, 'invoice_overdue', has_invoice_overdue,
    'status', d.status::text,
    'critical_boosted', (mid >= 100000 OR (has_invoice_overdue AND mid >= 25000)));
  INSERT INTO public.priority_scores (entity_type, entity_id, business_name, score, factors, priority_level, last_updated)
  VALUES ('deal', _deal_id, COALESCE(d.business_name,''), final_score, factors,
          public.priority_level_from_score(final_score), now())
  ON CONFLICT (entity_type, entity_id) DO UPDATE
    SET score = EXCLUDED.score, factors = EXCLUDED.factors,
        priority_level = EXCLUDED.priority_level,
        business_name = EXCLUDED.business_name, last_updated = now();
END; $function$

CREATE OR REPLACE FUNCTION public.priority_score_invoice(_invoice_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  inv public.invoices;
  days_overdue int := 0;
  expected numeric := 0;
  final_score int := 0;
  factors jsonb;
BEGIN
  SELECT * INTO inv FROM public.invoices WHERE id = _invoice_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF inv.status = 'PAID' THEN
    DELETE FROM public.priority_scores WHERE entity_type = 'invoice'::priority_entity_type AND entity_id = _invoice_id;
    RETURN;
  END IF;
  expected := COALESCE(inv.expected_amount, 0);
  days_overdue := GREATEST(0, (CURRENT_DATE - inv.due_date));
  final_score := LEAST(100, ROUND(days_overdue * 4 + (expected / 5000.0))::int);
  IF days_overdue > 14 THEN final_score := GREATEST(final_score, 90); END IF;
  IF days_overdue > 30 THEN final_score := GREATEST(final_score, 95); END IF;
  IF expected >= 50000 AND days_overdue > 0 THEN final_score := GREATEST(final_score, 85); END IF;
  IF expected >= 100000 AND days_overdue > 7 THEN final_score := 100; END IF;
  factors := jsonb_build_object(
    'expected_amount', expected, 'days_overdue', days_overdue,
    'status', inv.status, 'invoice_number', inv.invoice_number,
    'payment_risk_flag', inv.payment_risk_flag);
  INSERT INTO public.priority_scores (entity_type, entity_id, business_name, score, factors, priority_level, last_updated)
  VALUES ('invoice'::priority_entity_type, _invoice_id, COALESCE(inv.business_name,''), final_score, factors,
          public.priority_level_from_score(final_score), now())
  ON CONFLICT (entity_type, entity_id) DO UPDATE
    SET score = EXCLUDED.score, factors = EXCLUDED.factors,
        priority_level = EXCLUDED.priority_level,
        business_name = EXCLUDED.business_name, last_updated = now();
END; $function$

CREATE OR REPLACE FUNCTION public.process_retry_queue()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r record;
  processed int := 0;
  failed int := 0;
  delay_min int;
BEGIN
  FOR r IN
    SELECT * FROM public.retry_queue
     WHERE status = 'pending' AND next_retry_at <= now()
     ORDER BY next_retry_at ASC LIMIT 50
  LOOP
    BEGIN
      IF r.action_type = 'send_email' AND r.entity_type = 'email_queue' THEN
        -- Requeue: flip back to pending and schedule immediately
        UPDATE public.email_queue
           SET status = 'pending', scheduled_at = now()
         WHERE id = r.entity_id
           AND status IN ('delayed','throttled');

        UPDATE public.retry_queue
           SET status = 'completed', updated_at = now()
         WHERE id = r.id;
        processed := processed + 1;
      ELSE
        -- Unknown safe action — leave for manual handling
        UPDATE public.retry_queue
           SET status = 'failed', last_error = 'Unsupported action_type', updated_at = now()
         WHERE id = r.id;
        failed := failed + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      -- Exponential backoff: 5 / 15 / 60 min
      delay_min := CASE r.retry_count WHEN 0 THEN 5 WHEN 1 THEN 15 WHEN 2 THEN 60 ELSE 0 END;
      IF r.retry_count >= 3 THEN
        UPDATE public.retry_queue
           SET status = 'failed',
               last_error = LEFT(SQLERRM, 200),
               updated_at = now()
         WHERE id = r.id;
        failed := failed + 1;

        PERFORM public.log_system_event(
          'retry_exhausted', r.entity_type, r.entity_id, '',
          'critical',
          'Retry exhausted for ' || r.action_type::text || ' — manual intervention required',
          jsonb_build_object('last_error', SQLERRM)
        );
      ELSE
        UPDATE public.retry_queue
           SET retry_count = r.retry_count + 1,
               next_retry_at = now() + (delay_min || ' minutes')::interval,
               last_error = LEFT(SQLERRM, 200),
               updated_at = now()
         WHERE id = r.id;
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object('processed', processed, 'failed', failed);
END;
$function$

CREATE OR REPLACE FUNCTION public.proposals_reconcile_crm()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contact_id uuid;
  v_business_id uuid;
BEGIN
  IF NEW.contact_email IS NULL OR length(trim(NEW.contact_email)) = 0 THEN
    NEW.contact_id := NULL;
    NEW.business_id := NULL;
    NEW.crm_reconciliation_status := 'unmatched';
    RETURN NEW;
  END IF;

  SELECT id INTO v_contact_id
  FROM public.contacts
  WHERE lower(email) = lower(NEW.contact_email)
  LIMIT 1;

  IF v_contact_id IS NULL THEN
    NEW.contact_id := NULL;
    NEW.business_id := NULL;
    NEW.crm_reconciliation_status := 'unmatched';
  ELSE
    NEW.contact_id := v_contact_id;
    SELECT business_id INTO v_business_id
    FROM public.business_contact_relationships
    WHERE contact_id = v_contact_id AND business_id IS NOT NULL
    ORDER BY created_at ASC
    LIMIT 1;
    NEW.business_id := v_business_id;
    NEW.crm_reconciliation_status :=
      CASE WHEN v_business_id IS NULL THEN 'needs_review' ELSE 'matched' END;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.qtc_on_payment_succeeded()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  test_flag boolean := COALESCE(NEW.is_test_data, (NEW.audit_metadata->>'test_label') = 'LIVE_INTERNAL_TEST', false);
BEGIN
  IF NEW.payment_status = 'succeeded' AND (OLD.payment_status IS DISTINCT FROM 'succeeded') AND test_flag = false THEN
    INSERT INTO public.qtc_revenue_confirmations (
      business_id, contact_id, deal_id, invoice_id, payment_id,
      revenue_amount, currency, revenue_type, confirmation_source,
      business_name_snapshot, brand_name, saleable_asset_group, legal_entity, revenue_owner_entity,
      sale_ready, is_test_data
    )
    VALUES (
      NEW.business_id, NEW.contact_id, NEW.deal_id, NEW.invoice_id, NEW.id,
      COALESCE(NEW.net_amount, NEW.amount), NEW.currency, 'one_time', 'payment_provider',
      NEW.business_name_snapshot, NEW.brand_name, NEW.saleable_asset_group, NEW.legal_entity, NEW.revenue_owner_entity,
      COALESCE(NEW.sale_ready, false), false
    );
    NEW.confirmed_revenue := true;
    IF NEW.invoice_id IS NOT NULL THEN
      UPDATE public.qtc_invoices SET invoice_status = 'paid', paid_at = now() WHERE id = NEW.invoice_id;
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.qtc_payments_normalise()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Snapshot business name from businesses table if missing
  IF NEW.business_name_snapshot IS NULL AND NEW.business_id IS NOT NULL THEN
    SELECT name INTO NEW.business_name_snapshot FROM public.businesses WHERE id = NEW.business_id;
  END IF;

  -- Default legal entity to GSM_LLC if missing
  IF NEW.legal_entity IS NULL THEN
    NEW.legal_entity := 'GSM_LLC';
  END IF;
  IF NEW.revenue_owner_entity IS NULL THEN
    NEW.revenue_owner_entity := NEW.legal_entity;
  END IF;

  -- Gross defaults to legacy amount when not set
  IF (NEW.gross_amount IS NULL OR NEW.gross_amount = 0) AND NEW.amount IS NOT NULL THEN
    NEW.gross_amount := NEW.amount;
  END IF;

  -- Net = gross - tax - fees
  NEW.net_amount := COALESCE(NEW.gross_amount,0) - COALESCE(NEW.tax_amount,0) - COALESCE(NEW.stripe_fee_amount,0);

  -- is_test_data legacy support
  IF NEW.is_test_data IS NULL THEN
    NEW.is_test_data := COALESCE((NEW.audit_metadata->>'test_label') = 'LIVE_INTERNAL_TEST', false);
  END IF;

  -- Sale-ready: must have business_id, legal_entity, succeeded payment, not test, not temporary payout, not pending transfer
  NEW.sale_ready := (
    NEW.business_id IS NOT NULL
    AND NEW.legal_entity IS NOT NULL
    AND NEW.payment_status = 'succeeded'
    AND COALESCE(NEW.is_test_data, false) = false
    AND COALESCE(NEW.temporary_payout_account_used, false) = false
    AND COALESCE(NEW.transfer_required_to_primary_account, false) = false
  );

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.recalculate_priority(_entity_type priority_entity_type, _entity_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  CASE _entity_type
    WHEN 'deal' THEN PERFORM public.priority_score_deal(_entity_id);
    WHEN 'assignment' THEN PERFORM public.priority_score_assignment(_entity_id);
    WHEN 'contact' THEN PERFORM public.priority_score_contact(_entity_id);
    WHEN 'conversation' THEN PERFORM public.priority_score_conversation(_entity_id);
  END CASE;
  PERFORM public.generate_system_tasks_from_priority(_entity_type, _entity_id);
END; $function$

