END;
$function$

CREATE OR REPLACE FUNCTION public.recompute_business_risk_score(_business_name text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  total int := 0; prev_total int := 0; n int := 0;
  last_at timestamptz; trend text := 'stable'; is_high boolean := false;
  prev_score_val int := 0;
BEGIN
  IF COALESCE(_business_name,'') = '' THEN RETURN 0; END IF;

  SELECT COALESCE(SUM(public.severity_weight(severity)), 0),
         COUNT(*), MAX(created_at)
    INTO total, n, last_at
    FROM public.compliance_events
   WHERE business_name = _business_name
     AND resolved      = false
     AND created_at    > now() - interval '7 days';

  SELECT COALESCE(SUM(public.severity_weight(severity)), 0)
    INTO prev_total
    FROM public.compliance_events
   WHERE business_name = _business_name
     AND created_at    > now() - interval '14 days'
     AND created_at   <= now() - interval '7 days';

  IF total > 100 THEN total := 100; END IF;
  IF total < 0   THEN total := 0;   END IF;

  IF total > prev_total + 5 THEN trend := 'up';
  ELSIF total < prev_total - 5 THEN trend := 'down';
  ELSE trend := 'stable';
  END IF;
  is_high := (total > 70);

  SELECT score INTO prev_score_val FROM public.business_risk_scores
   WHERE business_name = _business_name;
  prev_score_val := COALESCE(prev_score_val, 0);

  INSERT INTO public.business_risk_scores
    (business_name, score, previous_score, risk_trend, high_risk, event_count, last_event_at)
  VALUES (_business_name, total, prev_score_val, trend, is_high, n, last_at)
  ON CONFLICT (business_name) DO UPDATE
    SET previous_score = public.business_risk_scores.score,
        score = EXCLUDED.score,
        risk_trend = EXCLUDED.risk_trend,
        high_risk = EXCLUDED.high_risk,
        event_count = EXCLUDED.event_count,
        last_event_at = EXCLUDED.last_event_at,
        updated_at = now();

  RETURN total;
END; $function$

CREATE OR REPLACE FUNCTION public.recompute_compliance_score(_entity_type compliance_entity_type, _entity_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  total int := 0; n int := 0; last_at timestamptz;
  prev_total int := 0;
  trend text := 'stable';
  is_high boolean := false;
  prev_score_val int := 0;
  bn text;
BEGIN
  -- current 7-day weighted total (open events)
  SELECT COALESCE(SUM(public.severity_weight(severity)), 0),
         COUNT(*), MAX(created_at)
    INTO total, n, last_at
    FROM public.compliance_events
   WHERE entity_type = _entity_type
     AND entity_id   = _entity_id
     AND resolved    = false
     AND created_at  > now() - interval '7 days';

  -- previous 7-day weighted total (8–14 days ago, all events)
  SELECT COALESCE(SUM(public.severity_weight(severity)), 0)
    INTO prev_total
    FROM public.compliance_events
   WHERE entity_type = _entity_type
     AND entity_id   = _entity_id
     AND created_at  > now() - interval '14 days'
     AND created_at <= now() - interval '7 days';

  IF total > 100 THEN total := 100; END IF;
  IF total < 0   THEN total := 0;   END IF;

  -- Trend
  IF total > prev_total + 5 THEN trend := 'up';
  ELSIF total < prev_total - 5 THEN trend := 'down';
  ELSE trend := 'stable';
  END IF;

  is_high := (total > 70);

  -- Capture previous score before upsert
  SELECT score INTO prev_score_val FROM public.compliance_scores
   WHERE entity_type = _entity_type AND entity_id = _entity_id;
  prev_score_val := COALESCE(prev_score_val, 0);

  INSERT INTO public.compliance_scores
    (entity_type, entity_id, score, previous_score, risk_trend, high_risk, event_count, last_event_at)
  VALUES (_entity_type, _entity_id, total, prev_score_val, trend, is_high, n, last_at)
  ON CONFLICT (entity_type, entity_id) DO UPDATE
    SET previous_score = public.compliance_scores.score,
        score = EXCLUDED.score,
        risk_trend = EXCLUDED.risk_trend,
        high_risk = EXCLUDED.high_risk,
        event_count = EXCLUDED.event_count,
        last_event_at = EXCLUDED.last_event_at,
        updated_at = now();

  -- Cascade: refresh business risk score using the most recent business_name we can find
  SELECT business_name INTO bn FROM public.compliance_events
   WHERE entity_type = _entity_type AND entity_id = _entity_id
     AND COALESCE(business_name,'') <> ''
   ORDER BY created_at DESC LIMIT 1;
  IF bn IS NOT NULL AND bn <> '' THEN
    PERFORM public.recompute_business_risk_score(bn);
  END IF;

  RETURN total;
END; $function$

CREATE OR REPLACE FUNCTION public.recompute_inbox_performance(_inbox_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sent int := 0; v_replies int := 0; v_bounces int := 0; v_today int := 0;
  v_reply numeric := 0; v_bounce numeric := 0; v_perf int := 50; v_rep int := 50;
BEGIN
  SELECT COUNT(*) INTO v_today FROM public.email_queue
   WHERE inbox_id = _inbox_id AND status = 'sent' AND sent_at >= date_trunc('day', now());
  SELECT COUNT(*) INTO v_sent FROM public.email_queue
   WHERE inbox_id = _inbox_id AND status = 'sent' AND sent_at > now() - interval '30 days';
  SELECT COUNT(*) INTO v_replies FROM public.email_events ev
    JOIN public.email_queue q ON q.contact_id = ev.contact_id
   WHERE q.inbox_id = _inbox_id AND ev.event_type = 'replied' AND ev.timestamp > now() - interval '30 days';
  SELECT COUNT(*) INTO v_bounces FROM public.email_events ev
    JOIN public.email_queue q ON q.contact_id = ev.contact_id
   WHERE q.inbox_id = _inbox_id AND ev.event_type = 'bounced' AND ev.timestamp > now() - interval '30 days';
  IF v_sent > 0 THEN
    v_reply := ROUND((v_replies::numeric / v_sent) * 100, 2);
    v_bounce := ROUND((v_bounces::numeric / v_sent) * 100, 2);
  END IF;
  SELECT reputation_score INTO v_rep FROM public.inboxes WHERE id = _inbox_id;
  v_perf := GREATEST(0, LEAST(100, ROUND(
    (COALESCE(v_rep,50) * 0.5) + (LEAST(v_reply, 30) * 1.5) - (v_bounce * 2)
  )::int));
  UPDATE public.inboxes SET emails_sent_today = v_today, reply_rate_per_inbox = v_reply,
    bounce_rate_per_inbox = v_bounce, performance_score = v_perf, updated_at = now()
   WHERE id = _inbox_id;
END; $function$

CREATE OR REPLACE FUNCTION public.recompute_proposal_score(_proposal_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  p public.internal_proposals;
  d public.demo_access;
  total_seconds integer := 0;
  score integer := 0;
BEGIN
  SELECT * INTO p FROM public.internal_proposals WHERE id = _proposal_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  IF p.status = 'accepted' THEN score := score + 50; END IF;
  IF p.viewed_at IS NOT NULL THEN score := score + 10; END IF;

  SELECT * INTO d FROM public.demo_access WHERE proposal_id = _proposal_id LIMIT 1;
  IF FOUND THEN
    score := score + LEAST(d.access_count * 10, 30);
    IF d.high_intent THEN score := score + 10; END IF;

    SELECT COALESCE(SUM(session_duration_seconds),0) INTO total_seconds
      FROM public.demo_events WHERE demo_id = d.id;
    IF total_seconds > 60 THEN score := score + 10; END IF;
  END IF;

  IF score > 100 THEN score := 100; END IF;
  IF score < 0 THEN score := 0; END IF;

  UPDATE public.internal_proposals SET proposal_score = score, updated_at = now()
   WHERE id = _proposal_id;

  RETURN score;
END;
$function$

CREATE OR REPLACE FUNCTION public.recompute_supplier_score(_supplier_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  total_finished int := 0;
  completed_n int := 0;
  failed_n int := 0;
  on_time_n int := 0;
  active_recent boolean := false;
  completion_pct numeric := 0;
  on_time_pct numeric := 0;
  failure_pct numeric := 0;
  score numeric := 50;
BEGIN
  SELECT
    COUNT(*) FILTER (WHERE status IN ('completed','failed')),
    COUNT(*) FILTER (WHERE status = 'completed'),
    COUNT(*) FILTER (WHERE status = 'failed'),
    COUNT(*) FILTER (WHERE status = 'completed'
                       AND expected_completion_date IS NOT NULL
                       AND completed_at::date <= expected_completion_date)
    INTO total_finished, completed_n, failed_n, on_time_n
  FROM public.assignments WHERE supplier_id = _supplier_id;

  SELECT (last_activity_at IS NOT NULL AND last_activity_at > now() - interval '30 days')
    INTO active_recent FROM public.suppliers WHERE id = _supplier_id;

  IF total_finished = 0 THEN
    score := 50; -- neutral until we have data
  ELSE
    completion_pct := (completed_n::numeric / total_finished) * 100;
    failure_pct    := (failed_n::numeric / total_finished) * 100;
    on_time_pct    := CASE WHEN completed_n > 0
                           THEN (on_time_n::numeric / completed_n) * 100
                           ELSE 0 END;
    score := (completion_pct * 0.5) + (on_time_pct * 0.3) - (failure_pct * 0.2);
    IF active_recent THEN score := score + 5; END IF;
  END IF;

  IF score < 0 THEN score := 0; END IF;
  IF score > 100 THEN score := 100; END IF;

  UPDATE public.suppliers
     SET supplier_score = ROUND(score)::int, updated_at = now()
   WHERE id = _supplier_id;

  RETURN ROUND(score)::int;
END;
$function$

CREATE OR REPLACE FUNCTION public.recompute_video_buyer_handover_ready(_video_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v RECORD;
  seg_count INT;
  ready BOOLEAN := false;
BEGIN
  SELECT id, external_url, privacy_status, approval_status, module_coverage, dashboard_area, video_type
    INTO v FROM public.video_library_items WHERE id = _video_id;
  IF NOT FOUND THEN RETURN false; END IF;

  SELECT COUNT(*) INTO seg_count FROM public.video_transcript_segments WHERE video_id = _video_id;

  ready := seg_count > 0
       AND v.external_url IS NOT NULL
       AND v.privacy_status IN ('approved_internal','approved_customer','approved_buyer')
       AND v.approval_status = 'approved'
       AND ( (v.module_coverage IS NOT NULL AND array_length(v.module_coverage,1) > 0)
             OR v.dashboard_area IS NOT NULL );

  UPDATE public.video_library_items SET buyer_handover_ready = ready WHERE id = _video_id;
  RETURN ready;
END $function$

CREATE OR REPLACE FUNCTION public.release_portfolio_contact(p_contact_id uuid, p_business_name text, p_reason text DEFAULT 'released'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_owner public.portfolio_contact_ownership%ROWTYPE;
  v_cooldown_days integer;
BEGIN
  SELECT cross_brand_cooldown_days INTO v_cooldown_days FROM public.portfolio_collision_policy LIMIT 1;
  v_cooldown_days := COALESCE(v_cooldown_days, 30);

  SELECT * INTO v_owner FROM public.portfolio_contact_ownership
  WHERE contact_id = p_contact_id AND status = 'active' AND business_name = p_business_name
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('decision', 'noop', 'reason_codes', ARRAY['no_active_ownership']);
  END IF;

  UPDATE public.portfolio_contact_ownership
     SET status = 'released', released_at = now(), reason_code = p_reason,
         cooldown_until = now() + (v_cooldown_days || ' days')::interval, updated_at = now()
   WHERE id = v_owner.id;

  INSERT INTO public.portfolio_ownership_events
    (contact_id, ownership_id, business_name, event_type, decision, reason_codes, actor_id)
  VALUES (p_contact_id, v_owner.id, p_business_name, 'release', 'allowed', ARRAY[p_reason], auth.uid());

  RETURN jsonb_build_object('decision', 'released', 'ownership_id', v_owner.id,
    'cooldown_days', v_cooldown_days);
END;
$function$

CREATE OR REPLACE FUNCTION public.reset_inbox_send_counts()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer;
BEGIN
  UPDATE public.inboxes SET current_send_count = 0, updated_at = now()
   WHERE current_send_count > 0;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_contact_timezone(_contact_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c public.contacts;
  tz text;
  ctry text;
BEGIN
  SELECT * INTO c FROM public.contacts WHERE id = _contact_id;
  IF NOT FOUND THEN RETURN 'UTC'; END IF;
  IF coalesce(c.timezone,'') <> '' THEN RETURN c.timezone; END IF;
  IF coalesce(c.country,'') <> '' THEN
    RETURN public.country_to_timezone(c.country);
  END IF;
  -- fallback to imported_leads.raw_data.country
  SELECT raw_data->>'country' INTO ctry
    FROM public.imported_leads WHERE contact_id = _contact_id LIMIT 1;
  IF coalesce(ctry,'') <> '' THEN
    RETURN public.country_to_timezone(ctry);
  END IF;
  RETURN 'UTC';
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_entity_country(_contact_id uuid, _business text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE resolved text;
BEGIN
  SELECT NULLIF(c.country, '') INTO resolved FROM public.contacts c WHERE c.id = _contact_id;
  IF resolved IS NOT NULL THEN RETURN resolved; END IF;
  SELECT NULLIF(il.raw_data->>'country', '') INTO resolved
    FROM public.imported_leads il WHERE il.contact_id = _contact_id LIMIT 1;
  IF resolved IS NOT NULL THEN RETURN resolved; END IF;
  IF _business IN ('UK','EU','DE','FR') THEN RETURN _business; END IF;
  RETURN 'GLOBAL';
END; $function$

CREATE OR REPLACE FUNCTION public.run_billionaire_enrichment_batches(p_max_batches integer DEFAULT 10, p_batch_size integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE r jsonb; out jsonb := '[]'::jsonb; i int := 0;
BEGIN
  WHILE i < p_max_batches LOOP
    r := public.process_billionaire_enrichment_batch(p_batch_size);
    EXIT WHEN (r->>'selected')::int = 0;
    out := out || jsonb_build_array(r);
    i := i + 1;
    EXIT WHEN (r->>'remaining')::int = 0;
  END LOOP;
  RETURN jsonb_build_object('batches', out, 'batches_run', i,
    'remaining', (SELECT count(*) FROM public.billionaire_enrichment_queue q
                  WHERE q.status IN ('pending','in_progress') OR COALESCE(q.batch_key,'') NOT LIKE 'access_2026_b%'));
END; $function$

CREATE OR REPLACE FUNCTION public.run_compliance_checks(_entity_type compliance_entity_type, _entity_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  CASE _entity_type
    WHEN 'message'    THEN PERFORM public.compliance_check_outbound_communication(_entity_id);
    WHEN 'contact'    THEN PERFORM public.compliance_check_contact(_entity_id);
    WHEN 'demo'       THEN PERFORM public.compliance_check_demo(_entity_id);
    WHEN 'proposal'   THEN PERFORM public.compliance_check_proposal(_entity_id);
    WHEN 'assignment' THEN PERFORM public.compliance_check_assignment(_entity_id);
    WHEN 'invoice'    THEN PERFORM public.compliance_check_invoice(_entity_id);
    WHEN 'payment'    THEN PERFORM public.compliance_check_payment(_entity_id);
    ELSE NULL;
  END CASE;
END; $function$

CREATE OR REPLACE FUNCTION public.run_domain_protection_check()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r RECORD; v_bounce_rate numeric; v_reply_rate numeric;
  v_sent int; v_bounced int; v_replied int;
  v_alerts int := 0; v_paused int := 0;
BEGIN
  FOR r IN
    SELECT i.id AS inbox_id, i.email_address, i.sending_domain_id, i.warmup_started_at
    FROM public.inboxes i WHERE i.active = true
  LOOP
    SELECT
      COUNT(*) FILTER (WHERE eq.status='sent' AND eq.sent_at > now() - interval '3 days'),
      COUNT(DISTINCT ev.id) FILTER (WHERE ev.event_type='bounced' AND ev.timestamp > now() - interval '3 days'),
      COUNT(DISTINCT ev.id) FILTER (WHERE ev.event_type='replied' AND ev.timestamp > now() - interval '3 days')
    INTO v_sent, v_bounced, v_replied
    FROM public.email_queue eq
    LEFT JOIN public.email_events ev ON ev.contact_id=eq.contact_id
    WHERE eq.inbox_id = r.inbox_id;

    IF v_sent < 10 THEN CONTINUE; END IF;
    v_bounce_rate := (v_bounced::numeric / NULLIF(v_sent,0)) * 100;
    v_reply_rate  := (v_replied::numeric / NULLIF(v_sent,0)) * 100;

    IF v_bounce_rate > 5 THEN
      INSERT INTO public.domain_protection_alerts(inbox_id, sending_domain_id, alert_type, severity, metric_value, threshold_value, message)
      VALUES (r.inbox_id, r.sending_domain_id, 'bounce_rate_exceeded', 'critical', v_bounce_rate, 5,
              format('Inbox %s bounce rate %.2f%% over 3d (>5%%)', r.email_address, v_bounce_rate));
      INSERT INTO public.system_events(event_type, severity, message, entity_type, entity_id)
      VALUES ('domain_bounce_high','critical',
              format('Bounce rate %.2f%% on %s — campaigns paused', v_bounce_rate, r.email_address),
              'inbox', r.inbox_id);
      INSERT INTO public.system_tasks(entity_type, entity_id, task_type, priority_score, reason)
      VALUES ('contact', r.inbox_id, 'review', 90, format('Domain protection: bounce rate %.2f%% on %s', v_bounce_rate, r.email_address))
      ON CONFLICT DO NOTHING;
      UPDATE public.inboxes SET active=false, paused_reason='bounce_rate_exceeded' WHERE id=r.inbox_id;
      UPDATE public.outreach_campaigns SET status='paused'
        WHERE status='active' AND id IN (SELECT DISTINCT campaign_id FROM public.email_queue WHERE inbox_id=r.inbox_id);
      v_alerts := v_alerts + 1; v_paused := v_paused + 1;
    ELSIF v_reply_rate < 1 AND r.warmup_started_at < now() - interval '3 days' THEN
      INSERT INTO public.domain_protection_alerts(inbox_id, sending_domain_id, alert_type, severity, metric_value, threshold_value, message)
      VALUES (r.inbox_id, r.sending_domain_id, 'reply_rate_low', 'high', v_reply_rate, 1,
              format('Inbox %s reply rate %.2f%% over 3d (<1%%)', r.email_address, v_reply_rate));
      INSERT INTO public.system_events(event_type, severity, message, entity_type, entity_id)
      VALUES ('domain_reply_low','high',
              format('Reply rate %.2f%% on %s — review messaging', v_reply_rate, r.email_address),
              'inbox', r.inbox_id);
      v_alerts := v_alerts + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('alerts_created', v_alerts, 'inboxes_paused', v_paused);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_inbox_credentials(_inbox_id uuid, _provider_type text, _smtp_host text, _smtp_port integer, _smtp_username text, _smtp_encryption text, _smtp_password text, _from_name text, _from_email text, _reply_to_email text, _enc_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
DECLARE
  v_pwd_enc bytea;
  v_set_at timestamptz;
  v_existing_pwd bytea;
BEGIN
  IF _provider_type NOT IN ('simulated','ionos_smtp') THEN
    RAISE EXCEPTION 'invalid provider_type %', _provider_type;
  END IF;
  IF _enc_key IS NULL OR length(_enc_key) < 16 THEN
    RAISE EXCEPTION 'encryption key missing or too short';
  END IF;

  SELECT smtp_password_enc INTO v_existing_pwd
    FROM public.inbox_credentials WHERE inbox_id = _inbox_id;

  IF _smtp_password IS NOT NULL AND length(_smtp_password) > 0 THEN
    v_pwd_enc := pgp_sym_encrypt(_smtp_password, _enc_key);
    v_set_at := now();
  ELSE
    v_pwd_enc := v_existing_pwd;
    v_set_at := (SELECT password_set_at FROM public.inbox_credentials WHERE inbox_id = _inbox_id);
  END IF;

  INSERT INTO public.inbox_credentials (
    inbox_id, provider_type, smtp_host, smtp_port, smtp_username,
    smtp_encryption, smtp_password_enc, password_set_at
  ) VALUES (
    _inbox_id, _provider_type::public.inbox_provider_type,
    _smtp_host, _smtp_port, _smtp_username, _smtp_encryption, v_pwd_enc, v_set_at
  )
  ON CONFLICT (inbox_id) DO UPDATE SET
    provider_type = EXCLUDED.provider_type,
    smtp_host = EXCLUDED.smtp_host,
    smtp_port = EXCLUDED.smtp_port,
    smtp_username = EXCLUDED.smtp_username,
    smtp_encryption = EXCLUDED.smtp_encryption,
    smtp_password_enc = EXCLUDED.smtp_password_enc,
    password_set_at = EXCLUDED.password_set_at,
    updated_at = now();

  UPDATE public.inboxes
     SET provider_type = _provider_type::public.inbox_provider_type,
         from_name = _from_name,
         from_email = _from_email,
         reply_to_email = _reply_to_email,
         live_readiness = CASE
           WHEN _provider_type = 'simulated' THEN 'simulated_only'::public.inbox_live_readiness
           WHEN v_pwd_enc IS NULL OR _smtp_host IS NULL OR _smtp_username IS NULL
                THEN 'not_configured'::public.inbox_live_readiness
           WHEN (SELECT live_readiness FROM public.inboxes WHERE id = _inbox_id)
                IN ('test_passed','live_ready')
                AND (_smtp_password IS NULL OR length(_smtp_password) = 0)
                THEN (SELECT live_readiness FROM public.inboxes WHERE id = _inbox_id)
           ELSE 'configured_not_tested'::public.inbox_live_readiness
         END,
         updated_at = now()
   WHERE id = _inbox_id;

  RETURN jsonb_build_object('ok', true, 'inbox_id', _inbox_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_inbox_inbound_config(_inbox_id uuid, _inbound_provider text, _imap_host text, _imap_port integer, _imap_ssl boolean, _imap_username text, _imap_password text, _reuse_smtp_password boolean, _polling_enabled boolean, _monitored_mailbox text, _enc_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
DECLARE v_pwd_enc bytea; v_set_at timestamptz; v_existing_pwd bytea; v_existing_smtp_pwd bytea;
BEGIN
  IF _inbound_provider NOT IN ('none','ionos_imap') THEN RAISE EXCEPTION 'invalid inbound_provider %', _inbound_provider; END IF;
  IF _enc_key IS NULL OR length(_enc_key) < 16 THEN RAISE EXCEPTION 'encryption key missing or too short'; END IF;
  SELECT imap_password_enc, smtp_password_enc INTO v_existing_pwd, v_existing_smtp_pwd FROM public.inbox_credentials WHERE inbox_id = _inbox_id;
  IF _reuse_smtp_password IS TRUE THEN
    IF v_existing_smtp_pwd IS NULL THEN RAISE EXCEPTION 'cannot reuse SMTP password — none stored'; END IF;
    v_pwd_enc := v_existing_smtp_pwd; v_set_at := now();
  ELSIF _imap_password IS NOT NULL AND length(_imap_password) > 0 THEN
    v_pwd_enc := pgp_sym_encrypt(_imap_password, _enc_key); v_set_at := now();
  ELSE
    v_pwd_enc := v_existing_pwd; v_set_at := (SELECT imap_password_set_at FROM public.inbox_credentials WHERE inbox_id = _inbox_id);
  END IF;
  INSERT INTO public.inbox_credentials (
    inbox_id, provider_type, imap_host, imap_port, imap_ssl, imap_username, imap_password_enc, imap_password_set_at
  ) VALUES (
    _inbox_id,
    COALESCE((SELECT provider_type FROM public.inbox_credentials WHERE inbox_id = _inbox_id), 'simulated')::public.inbox_provider_type,
    _imap_host, _imap_port, COALESCE(_imap_ssl, true), _imap_username, v_pwd_enc, v_set_at
  ) ON CONFLICT (inbox_id) DO UPDATE
    SET imap_host = EXCLUDED.imap_host, imap_port = EXCLUDED.imap_port, imap_ssl = EXCLUDED.imap_ssl,
        imap_username = EXCLUDED.imap_username, imap_password_enc = EXCLUDED.imap_password_enc,
        imap_password_set_at = EXCLUDED.imap_password_set_at, updated_at = now();
  UPDATE public.inboxes
     SET inbound_provider = _inbound_provider::public.inbound_provider_type,
         inbound_polling_enabled = COALESCE(_polling_enabled, false),
         monitored_mailbox = _monitored_mailbox,
         inbound_status = CASE
           WHEN _inbound_provider = 'none' THEN 'not_configured'::public.inbound_status_type
           WHEN inbound_status IN ('inbound_test_passed','live_ready') THEN inbound_status
           ELSE 'configured_not_tested'::public.inbound_status_type END,
         updated_at = now()
   WHERE id = _inbox_id;
  RETURN jsonb_build_object('ok', true);
END; $function$

CREATE OR REPLACE FUNCTION public.score_contact(_contact_id uuid, _business_name text DEFAULT NULL::text)
 RETURNS lead_scores
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c public.contacts%ROWTYPE;
  s integer := 40;
  reasons text[] := ARRAY[]::text[];
  result public.lead_scores;
BEGIN
  SELECT * INTO c FROM public.contacts WHERE id = _contact_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  IF COALESCE(c.role, '') <> '' THEN s := s + 20; reasons := array_append(reasons, 'has role'); END IF;
  IF COALESCE(c.company, '') <> '' THEN s := s + 20; reasons := array_append(reasons, 'has company'); END IF;
  IF _business_name IS NOT NULL AND COALESCE(c.assigned_business, '') = _business_name THEN
    s := s + 20; reasons := array_append(reasons, 'business match');
  END IF;
  IF s > 100 THEN s := 100; END IF;

  INSERT INTO public.lead_scores (contact_id, score, reason)
  VALUES (_contact_id, s, array_to_string(reasons, ', '))
  ON CONFLICT (contact_id) DO UPDATE
    SET score = EXCLUDED.score,
        reason = EXCLUDED.reason,
        updated_at = now()
  RETURNING * INTO result;

  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.score_proposal_quality(_proposal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  p public.internal_proposals; completeness int := 0; clarity int := 0;
  pricing_realism int := 0; total int := 0; flags jsonb := '[]'::jsonb;
  cost_min numeric := 0; cost_max numeric := 0;
  expected_min numeric := 0; expected_max numeric := 0; bullets int := 0;
BEGIN
  SELECT * INTO p FROM public.internal_proposals WHERE id = _proposal_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false); END IF;

  completeness := completeness + (CASE WHEN length(COALESCE(p.suggested_solution,'')) > 100 THEN 10 ELSE 0 END);
  completeness := completeness + (CASE WHEN length(COALESCE(p.estimated_scope,'')) > 80 THEN 8 ELSE 0 END);
  completeness := completeness + (CASE WHEN length(COALESCE(p.estimated_timeline,'')) > 5 THEN 5 ELSE 0 END);
  completeness := completeness + (CASE WHEN length(COALESCE(p.estimated_cost_range,'')) > 5 THEN 5 ELSE 0 END);
  completeness := completeness + (CASE WHEN p.architecture_components IS NOT NULL AND jsonb_array_length(p.architecture_components) > 0 THEN 7 ELSE 0 END);
  completeness := completeness + (CASE WHEN length(COALESCE(p.estimated_roi_summary,'')) > 30 THEN 5 ELSE 0 END);
  IF length(COALESCE(p.suggested_solution,'')) < 50 THEN flags := flags || '"missing_solution"'::jsonb; END IF;
  IF p.architecture_components IS NULL OR jsonb_array_length(p.architecture_components) = 0 THEN flags := flags || '"no_architecture"'::jsonb; END IF;

  bullets := (length(COALESCE(p.suggested_solution,'')) - length(replace(COALESCE(p.suggested_solution,''), E'\n', '')));
  clarity := clarity + LEAST(15, bullets * 2);
  clarity := clarity + (CASE WHEN COALESCE(p.suggested_solution,'') ~* '(•|\*|\-|^\d\.)' THEN 5 ELSE 0 END);
  clarity := clarity + (CASE WHEN length(COALESCE(p.suggested_solution,'')) BETWEEN 200 AND 4000 THEN 10 ELSE 0 END);
  IF length(COALESCE(p.suggested_solution,'')) > 8000 THEN flags := flags || '"too_long"'::jsonb; END IF;

  IF p.estimated_cost_breakdown IS NOT NULL THEN
    cost_min := COALESCE((p.estimated_cost_breakdown->>'min')::numeric, 0);
    cost_max := COALESCE((p.estimated_cost_breakdown->>'max')::numeric, 0);
  END IF;

  CASE COALESCE(p.project_scale,'medium')
    WHEN 'small' THEN expected_min := 2000; expected_max := 25000;
    WHEN 'medium' THEN expected_min := 15000; expected_max := 100000;
    WHEN 'large' THEN expected_min := 60000; expected_max := 500000;
    WHEN 'enterprise' THEN expected_min := 150000; expected_max := 2000000;
    ELSE expected_min := 5000; expected_max := 200000;
  END CASE;

  IF cost_min > 0 AND cost_max > 0 AND cost_min < cost_max THEN
    pricing_realism := pricing_realism + 10;
    IF cost_min >= expected_min * 0.5 AND cost_max <= expected_max * 1.5 THEN
      pricing_realism := pricing_realism + 20;
    ELSE
      pricing_realism := pricing_realism + 5;
      flags := flags || '"pricing_outside_band"'::jsonb;
    END IF;
  ELSE
    flags := flags || '"missing_or_invalid_pricing"'::jsonb;
  END IF;

  total := GREATEST(0, LEAST(100, completeness + clarity + pricing_realism));
  UPDATE public.internal_proposals
     SET proposal_quality_score = total, quality_flags = flags, updated_at = now()
   WHERE id = _proposal_id;
  RETURN jsonb_build_object('ok', true, 'score', total,
    'completeness', completeness, 'clarity', clarity,
    'pricing_realism', pricing_realism, 'flags', flags);
END; $function$

