CREATE OR REPLACE FUNCTION public.set_system_mode(_mode text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old text;
  v_configured boolean;
  v_test_passed timestamptz;
BEGIN
  IF _mode NOT IN ('live','sandbox') THEN
    RAISE EXCEPTION 'invalid mode %, must be live or sandbox', _mode;
  END IF;

  IF _mode = 'live' THEN
    SELECT COALESCE((value)::boolean, false)
      INTO v_configured
      FROM public.system_settings
     WHERE key = 'outbound_provider_configured';

    SELECT NULLIF(value #>> '{}', '')::timestamptz
      INTO v_test_passed
      FROM public.system_settings
     WHERE key = 'outbound_provider_test_passed_at';

    IF NOT COALESCE(v_configured, false) OR v_test_passed IS NULL THEN
      RAISE EXCEPTION
        'Cannot switch system_mode to live: outbound email provider is not configured or has not passed a real test send. The outreach worker is currently in simulated mode.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  v_old := public.get_system_mode();
  INSERT INTO public.system_settings(key, value, updated_at)
  VALUES ('system_mode', to_jsonb(_mode), now())
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  INSERT INTO public.activity_log(event_type, description, entity_type, entity_id)
  VALUES ('system_mode_changed', format('System mode switched from %s to %s', v_old, _mode), 'system', NULL);

  INSERT INTO public.system_events(event_type, severity, message, metadata)
  VALUES (
    'system_mode_changed',
    CASE WHEN _mode = 'live' THEN 'high'::system_event_severity ELSE 'medium'::system_event_severity END,
    format('System mode is now %s', _mode),
    jsonb_build_object('previous_mode', v_old, 'new_mode', _mode)
  );

  RETURN _mode;
END;
$function$

CREATE OR REPLACE FUNCTION public.snapshot_deal_compliance_on_won()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  contact_score int := 0;
  business_score int := 0;
BEGIN
  IF NEW.status = 'WON' AND (OLD.status IS DISTINCT FROM 'WON') THEN
    IF NEW.contact_id IS NOT NULL THEN
      SELECT COALESCE(score,0) INTO contact_score
        FROM public.compliance_scores
       WHERE entity_type = 'contact' AND entity_id = NEW.contact_id;
    END IF;
    IF COALESCE(NEW.business_name,'') <> '' THEN
      SELECT COALESCE(score,0) INTO business_score
        FROM public.business_risk_scores
       WHERE business_name = NEW.business_name;
    END IF;
    NEW.compliance_score_at_close := GREATEST(COALESCE(contact_score,0), COALESCE(business_score,0));
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.social_relationship_claim_action(p_action_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status TEXT;
BEGIN
  SELECT action_status INTO v_status
  FROM public.social_relationship_action_queue
  WHERE id = p_action_id
  FOR UPDATE;

  IF v_status IS NULL THEN
    RETURN 'not_found';
  END IF;

  -- Anything already submitted (or resolved) can never be claimed again.
  IF v_status IN ('submitting','sent','accepted','replied','submission_unknown') THEN
    RETURN 'duplicate';
  END IF;

  IF v_status NOT IN ('ready','retrying') THEN
    RETURN 'not_claimable';
  END IF;

  UPDATE public.social_relationship_action_queue
  SET action_status = 'submitting',
      submitted_at = now(),
      attempt_count = attempt_count + 1,
      updated_at = now()
  WHERE id = p_action_id;

  RETURN 'claimed';
END;
$function$

