CREATE OR REPLACE FUNCTION public.trg_reputation_from_email_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  q public.email_queue;
  rep_event public.reputation_event_type;
BEGIN
  -- Try to correlate to a queue row (email_id stores queue id in our send-worker)
  BEGIN
    SELECT * INTO q FROM public.email_queue WHERE id = NEW.email_id::uuid;
  EXCEPTION WHEN others THEN
    q := NULL;
  END;

  IF q.inbox_id IS NULL THEN RETURN NEW; END IF;

  rep_event := CASE NEW.event_type::text
    WHEN 'bounced'   THEN 'bounce'::public.reputation_event_type
    WHEN 'opened'    THEN 'open'::public.reputation_event_type
    WHEN 'replied'   THEN 'reply'::public.reputation_event_type
    WHEN 'sent'      THEN 'sent'::public.reputation_event_type
    WHEN 'delivered' THEN 'delivered'::public.reputation_event_type
    ELSE NULL
  END;
  IF rep_event IS NULL THEN RETURN NEW; END IF;

  PERFORM public.apply_reputation_event(q.inbox_id, NEW.contact_id, rep_event, NEW.event_type::text);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_spam_on_dnc()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE q public.email_queue;
BEGIN
  IF NEW.status = 'DO_NOT_CONTACT' AND OLD.status IS DISTINCT FROM 'DO_NOT_CONTACT' THEN
    -- find most recent sent queue entry for this contact
    SELECT * INTO q FROM public.email_queue
     WHERE contact_id = NEW.id AND status = 'sent'
     ORDER BY sent_at DESC LIMIT 1;
    IF q.inbox_id IS NOT NULL THEN
      PERFORM public.apply_reputation_event(q.inbox_id, NEW.id, 'spam', 'Contact moved to DO_NOT_CONTACT');
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.try_auto_assign_supplier_on_deal_won()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  matches uuid[];
  picked_supplier uuid;
BEGIN
  IF NEW.status <> 'WON' OR OLD.status = 'WON' THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM public.assignments WHERE deal_id = NEW.id) THEN RETURN NEW; END IF;

  SELECT array_agg(s.id ORDER BY s.id) INTO matches
    FROM public.suppliers s
    JOIN public.supplier_availability sa ON sa.supplier_id = s.id
   WHERE s.status = 'APPROVED'
     AND sa.status = 'available'
     AND (NEW.business_name = '' OR s.business_name = '' OR s.business_name = NEW.business_name)
     AND (
       COALESCE(array_length(NEW.required_skills, 1), 0) = 0
       OR s.skills && NEW.required_skills
     );

  IF matches IS NOT NULL AND array_length(matches, 1) = 1 THEN
    picked_supplier := matches[1];
    INSERT INTO public.assignments (supplier_id, deal_id, contact_id, business_name, status, auto_assigned, required_skills)
    VALUES (picked_supplier, NEW.id, NEW.contact_id, COALESCE(NEW.business_name,''), 'assigned', true, NEW.required_skills);
    INSERT INTO public.activity_log (event_type, description, entity_type, entity_id)
    VALUES ('assignment_auto_created',
            'Auto-assigned supplier to won deal ' || NEW.deal_name,
            'assignment', NEW.id);
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.validate_campaign_activation(_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_campaign public.outreach_campaigns;
  v_issues text[] := '{}';
  v_messages jsonb := '{}'::jsonb;
  v_active_inboxes int;
  v_mapped_inboxes int;
  v_low_rep int;
BEGIN
  SELECT * INTO v_campaign FROM public.outreach_campaigns WHERE id=_campaign_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed', false, 'issues', jsonb_build_array('campaign_not_found'));
  END IF;

  SELECT COUNT(*) INTO v_active_inboxes
    FROM public.inboxes
   WHERE business_name = v_campaign.business_name AND active = true;
  IF v_active_inboxes = 0 THEN
    v_issues := array_append(v_issues, 'no_active_inbox_for_business');
    v_messages := v_messages || jsonb_build_object(
      'no_active_inbox_for_business',
      format('No active inbox is configured for %s. Add and activate an inbox before activating campaigns.', v_campaign.business_name)
    );
  END IF;

  -- An inbox is "inbound-mapped" if EITHER:
  --   (a) classic webhook+domain path is wired, OR
  --   (b) IMAP polling is enabled with a monitored mailbox and inbound status has reached at least test_passed.
  SELECT COUNT(*) INTO v_mapped_inboxes
    FROM public.inboxes
   WHERE business_name = v_campaign.business_name
     AND active = true
     AND (
       (COALESCE(inbound_webhook_url,'') <> '' AND sending_domain_id IS NOT NULL)
       OR (
         COALESCE(inbound_polling_enabled, false) = true
         AND COALESCE(monitored_mailbox, '') <> ''
         AND inbound_status IN ('inbound_test_passed'::public.inbound_status_type, 'live_ready'::public.inbound_status_type)
       )
     );
  IF v_active_inboxes > 0 AND v_mapped_inboxes = 0 THEN
    v_issues := array_append(v_issues, 'inbound_mapping_missing');
    v_messages := v_messages || jsonb_build_object(
      'inbound_mapping_missing',
      'This campaign needs an inbound reply route. Configure either inbound IMAP polling (set the monitored mailbox/folder and pass an inbound test) or an inbound webhook with a sending domain on at least one inbox for this business.'
    );
  END IF;

  SELECT COUNT(*) INTO v_low_rep
    FROM public.inboxes
   WHERE business_name = v_campaign.business_name
     AND active = true
     AND reputation_score < 50;
  IF v_low_rep > 0 THEN
    v_issues := array_append(v_issues, 'inbox_reputation_below_50');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.sending_domains sd
    JOIN public.inboxes i ON i.sending_domain_id = sd.id
    WHERE i.business_name = v_campaign.business_name AND sd.domain_reputation_score < 20
  ) THEN
    v_issues := array_append(v_issues, 'sending_domain_paused');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.outreach_sequences WHERE campaign_id=_campaign_id) THEN
    v_issues := array_append(v_issues, 'no_sequences_configured');
  END IF;

  RETURN jsonb_build_object(
    'allowed', cardinality(v_issues)=0,
    'issues', COALESCE(to_jsonb(v_issues), '[]'::jsonb),
    'messages', v_messages,
    'campaign_id', _campaign_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_full_system_coverage()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total_pages integer;
  v_doc_pages integer;
  v_total_tables integer;
  v_doc_tables integer;
  v_total_funcs integer;
  v_doc_funcs integer;
  v_total_wf integer;
  v_doc_wf integer;
  v_total_rules integer;
  v_doc_rules integer;
  v_total_integrations integer;
  v_doc_integrations integer;
  v_total_flows integer;
  v_doc_flows integer;
  v_total_content integer;
  v_score integer;
  v_gaps integer := 0;
  v_details jsonb := '{}'::jsonb;
  v_report_id uuid;
  v_orphan_check jsonb;
  v_runtime_check jsonb;
  v_table record;
  v_func record;
BEGIN
  v_total_pages := 100;
  SELECT COUNT(*) INTO v_doc_pages FROM public.system_pages_index;
  IF v_doc_pages > v_total_pages THEN v_total_pages := v_doc_pages; END IF;

  SELECT COUNT(*) INTO v_total_tables
  FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE';
  SELECT COUNT(*) INTO v_doc_tables FROM public.system_backend_objects WHERE object_kind='table';

  SELECT COUNT(*) INTO v_total_funcs
  FROM information_schema.routines WHERE routine_schema='public' AND routine_type='FUNCTION';
  SELECT COUNT(*) INTO v_doc_funcs FROM public.system_backend_objects WHERE object_kind='function';

  SELECT COUNT(*) INTO v_doc_wf FROM public.system_workflows_full;
  v_total_wf := GREATEST(v_doc_wf, 10);
  SELECT COUNT(*) INTO v_doc_rules FROM public.system_rules;
  v_total_rules := GREATEST(v_doc_rules, 19);
  SELECT COUNT(*) INTO v_doc_integrations FROM public.system_integrations_full;
  v_total_integrations := GREATEST(v_doc_integrations, 5);
  SELECT COUNT(*) INTO v_doc_flows FROM public.system_data_flows;
  v_total_flows := GREATEST(v_doc_flows, 5);
  SELECT COUNT(*) INTO v_total_content FROM public.system_content;

  FOR v_table IN
    SELECT t.table_name FROM information_schema.tables t
    LEFT JOIN public.system_backend_objects b ON b.object_kind='table' AND b.object_name=t.table_name
    WHERE t.table_schema='public' AND t.table_type='BASE TABLE' AND b.id IS NULL
  LOOP
    v_gaps := v_gaps + 1;
    INSERT INTO public.system_events (event_type, entity_type, severity, message, metadata)
    VALUES ('coverage_gap_table','system_mirror','critical',
      'Undocumented table: ' || v_table.table_name,
      jsonb_build_object('table', v_table.table_name));
  END LOOP;

  FOR v_func IN
    SELECT r.routine_name FROM information_schema.routines r
    LEFT JOIN public.system_backend_objects b ON b.object_kind='function' AND b.object_name=r.routine_name
    WHERE r.routine_schema='public' AND r.routine_type='FUNCTION' AND b.id IS NULL
  LOOP
    v_gaps := v_gaps + 1;
    INSERT INTO public.system_events (event_type, entity_type, severity, message, metadata)
    VALUES ('coverage_gap_function','system_mirror','critical',
      'Undocumented function: ' || v_func.routine_name,
      jsonb_build_object('function', v_func.routine_name));
  END LOOP;

  v_orphan_check := public.detect_orphan_content();
  v_runtime_check := public.validate_runtime_vs_documentation();
  v_gaps := v_gaps
          + COALESCE((v_orphan_check->>'orphans_found')::int, 0)
          + COALESCE((v_runtime_check->>'mismatches_found')::int, 0);

  v_score := ROUND(
    (LEAST(v_doc_pages, v_total_pages)::numeric / NULLIF(v_total_pages,0)) * 20 +
    (v_doc_tables::numeric / NULLIF(v_total_tables,0)) * 20 +
    (v_doc_funcs::numeric  / NULLIF(v_total_funcs,0))  * 20 +
    (v_doc_wf::numeric     / NULLIF(v_total_wf,0))     * 10 +
    (v_doc_rules::numeric  / NULLIF(v_total_rules,0))  * 10 +
    (v_doc_integrations::numeric / NULLIF(v_total_integrations,0)) * 10 +
    (v_doc_flows::numeric  / NULLIF(v_total_flows,0))  * 10
  )::int;

  v_details := jsonb_build_object(
    'pages', jsonb_build_object('documented', v_doc_pages, 'total', v_total_pages),
    'tables', jsonb_build_object('documented', v_doc_tables, 'total', v_total_tables),
    'functions', jsonb_build_object('documented', v_doc_funcs, 'total', v_total_funcs),
    'workflows', jsonb_build_object('documented', v_doc_wf, 'total', v_total_wf),
    'rules', jsonb_build_object('documented', v_doc_rules, 'total', v_total_rules),
    'integrations', jsonb_build_object('documented', v_doc_integrations, 'total', v_total_integrations),
    'data_flows', jsonb_build_object('documented', v_doc_flows, 'total', v_total_flows),
    'content_count', v_total_content,
    'orphan_content', v_orphan_check,
    'runtime_check', v_runtime_check
  );

  INSERT INTO public.system_coverage_reports (
    total_pages, documented_pages, total_tables, documented_tables,
    total_functions, documented_functions, total_workflows, documented_workflows,
    total_rules, documented_rules, coverage_score, gaps_found, details
  ) VALUES (
    v_total_pages, v_doc_pages, v_total_tables, v_doc_tables,
    v_total_funcs, v_doc_funcs, v_total_wf, v_doc_wf,
    v_total_rules, v_doc_rules, v_score, v_gaps, v_details
  ) RETURNING id INTO v_report_id;

  -- Only raise the blocking "below 100%" event when there are REAL gaps.
  -- A score that dips below 100% with zero gaps is informational only.
  IF v_gaps > 0 THEN
    INSERT INTO public.system_events (event_type, entity_type, severity, message, metadata)
    VALUES ('coverage_below_100','system_mirror','critical',
      'System coverage below 100% (' || v_score || '%) — ' || v_gaps || ' gap(s)',
      v_details);
    INSERT INTO public.activity_log (event_type, description, entity_type)
    VALUES ('system_alert','Coverage validation: '||v_score||'% with '||v_gaps||' gaps','system_mirror');
  END IF;

  RETURN jsonb_build_object(
    'report_id', v_report_id,
    'coverage_score', v_score,
    'gaps_found', v_gaps,
    'details', v_details
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_go_live_readiness()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_issues text[] := '{}'; v_mode text;
  v_inboxes int; v_unmapped int; v_domains int; v_active_campaigns int;
BEGIN
  v_mode := public.get_system_mode();
  SELECT COUNT(*) INTO v_inboxes FROM public.inboxes WHERE active=true;
  IF v_inboxes = 0 THEN v_issues := array_append(v_issues, 'no_active_inboxes'); END IF;
  SELECT COUNT(*) INTO v_unmapped FROM public.inboxes
    WHERE active=true AND (inbound_webhook_url='' OR sending_domain_id IS NULL);
  IF v_unmapped > 0 THEN v_issues := array_append(v_issues, format('%s_inboxes_unmapped', v_unmapped)); END IF;
  SELECT COUNT(*) INTO v_domains FROM public.sending_domains;
  IF v_domains = 0 THEN v_issues := array_append(v_issues, 'no_sending_domain_configured'); END IF;
  IF v_domains > 0 AND NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema='public' AND table_name='sending_domains'
      AND column_name IN ('spf_verified','dkim_verified','dmarc_verified')
  ) THEN
    v_issues := array_append(v_issues, 'spf_dkim_dmarc_unverified');
  END IF;
  SELECT COUNT(*) INTO v_active_campaigns FROM public.outreach_campaigns WHERE status='active';
  IF v_active_campaigns = 0 AND v_mode='live' THEN
    v_issues := array_append(v_issues, 'no_active_campaign');
  END IF;
  RETURN jsonb_build_object(
    'ready', cardinality(v_issues)=0,
    'mode', v_mode,
    'issues', COALESCE(to_jsonb(v_issues), '[]'::jsonb),
    'active_inboxes', v_inboxes,
    'unmapped_inboxes', v_unmapped,
    'sending_domains', v_domains,
    'active_campaigns', v_active_campaigns,
    'checked_at', now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_inbox_mapping(_inbox_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_inbox public.inboxes; v_issues text[] := '{}';
BEGIN
  SELECT * INTO v_inbox FROM public.inboxes WHERE id=_inbox_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid', false, 'issues', jsonb_build_array('inbox_not_found'));
  END IF;
  IF v_inbox.inbound_webhook_url = '' THEN v_issues := array_append(v_issues, 'inbound_webhook_missing'); END IF;
  IF v_inbox.sending_domain_id IS NULL THEN v_issues := array_append(v_issues, 'sending_domain_unmapped'); END IF;
  IF NOT v_inbox.active THEN v_issues := array_append(v_issues, 'inbox_inactive'); END IF;
  RETURN jsonb_build_object('valid', cardinality(v_issues)=0,
                            'issues', COALESCE(to_jsonb(v_issues), '[]'::jsonb),
                            'inbox_id', v_inbox.id);
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_runtime_vs_documentation()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_mismatches jsonb := '[]'::jsonb;
  v_count integer := 0;
  v_workflow record;
  v_required_tables text[];
  v_table text;
  v_exists boolean;
BEGIN
  -- For each documented workflow, verify that every linked_table on each step actually exists
  FOR v_workflow IN
    SELECT w.workflow_key, w.workflow_name, s.step_index, s.step_name,
           string_to_array(COALESCE(s.linked_tables, ''), ',') AS tables_arr
    FROM public.system_workflows_full w
    JOIN public.system_workflow_steps s ON s.workflow_id = w.id
  LOOP
    FOREACH v_table IN ARRAY v_workflow.tables_arr LOOP
      v_table := trim(v_table);
      IF v_table = '' THEN CONTINUE; END IF;
      SELECT EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name = v_table
      ) INTO v_exists;
      IF NOT v_exists THEN
        v_count := v_count + 1;
        v_mismatches := v_mismatches || jsonb_build_object(
          'workflow', v_workflow.workflow_key,
          'step', v_workflow.step_name,
          'missing_table', v_table
        );
      END IF;
    END LOOP;
  END LOOP;

  IF v_count > 0 THEN
    INSERT INTO public.system_events (event_type, entity_type, severity, message, metadata)
    VALUES (
      'runtime_documentation_mismatch',
      'system_mirror',
      'critical',
      'Runtime/documentation mismatch: ' || v_count || ' issue(s) detected',
      jsonb_build_object('mismatches', v_mismatches)
    );
    INSERT INTO public.activity_log (event_type, description, entity_type)
    VALUES ('system_alert', 'Runtime vs documentation mismatch detected (' || v_count || ')', 'system_mirror');
  END IF;

  RETURN jsonb_build_object(
    'mismatches_found', v_count,
    'details', v_mismatches,
    'checked_at', now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_system_integrity()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  orphan_proposals int := 0; deals_no_contact int := 0;
  assignments_no_deal int := 0; invoices_no_deal int := 0;
  queue_no_inbox int := 0; result jsonb;
BEGIN
  SELECT COUNT(*) INTO orphan_proposals FROM public.internal_proposals p
    LEFT JOIN public.contacts c ON c.id = p.contact_id
   WHERE p.contact_id IS NULL OR c.id IS NULL;
  SELECT COUNT(*) INTO deals_no_contact FROM public.deals WHERE contact_id IS NULL;
  SELECT COUNT(*) INTO assignments_no_deal FROM public.assignments a
    LEFT JOIN public.deals d ON d.id = a.deal_id WHERE a.deal_id IS NULL OR d.id IS NULL;
  SELECT COUNT(*) INTO invoices_no_deal FROM public.invoices i
    LEFT JOIN public.deals d ON d.id = i.deal_id WHERE i.deal_id IS NULL OR d.id IS NULL;
  SELECT COUNT(*) INTO queue_no_inbox FROM public.email_queue
   WHERE status IN ('pending','delayed') AND inbox_id IS NULL;

  IF orphan_proposals > 0 THEN
    PERFORM public.log_system_event('integrity_orphan_proposals','system',NULL,'',
      'medium','Found '||orphan_proposals||' proposals without a valid contact',
      jsonb_build_object('count',orphan_proposals));
  END IF;
  IF deals_no_contact > 0 THEN
    PERFORM public.log_system_event('integrity_deals_missing_contact','system',NULL,'',
      'high','Found '||deals_no_contact||' deals without contact_id',
      jsonb_build_object('count',deals_no_contact));
  END IF;
  IF assignments_no_deal > 0 THEN
    PERFORM public.log_system_event('integrity_assignments_no_deal','system',NULL,'',
      'high','Found '||assignments_no_deal||' assignments not linked to a deal',
      jsonb_build_object('count',assignments_no_deal));
  END IF;
  IF invoices_no_deal > 0 THEN
    PERFORM public.log_system_event('integrity_invoices_no_deal','system',NULL,'',
      'high','Found '||invoices_no_deal||' invoices not linked to a deal',
      jsonb_build_object('count',invoices_no_deal));
  END IF;
  IF queue_no_inbox > 0 THEN
    PERFORM public.log_system_event('integrity_queue_no_inbox','system',NULL,'',
      'medium','Found '||queue_no_inbox||' pending emails without an inbox',
      jsonb_build_object('count',queue_no_inbox));
  END IF;

  result := jsonb_build_object(
    'orphan_proposals', orphan_proposals,
    'deals_missing_contact', deals_no_contact,
    'assignments_no_deal', assignments_no_deal,
    'invoices_no_deal', invoices_no_deal,
    'queue_no_inbox', queue_no_inbox,
    'checked_at', now());
  INSERT INTO public.activity_log (event_type, description, entity_type, entity_id)
  VALUES ('system_integrity_check', 'Integrity check: ' || result::text, 'system', NULL);
  RETURN result;
END; $function$
